    type: "city",
    parent: "AM-SH",
    coords: [43.8416, 40.7942],
    name: { de: "Gjumri", hu: "Gjümri", ro: "Gyumri", en: "Gyumri"},
    image: "/poi-images/armenia-gyumri-cities-v2.webp",
    description: {
      de: "Gjumri ist die zweitgrößte Stadt in Armenien, berühmt für ihre historische Architektur und ihr reiches kulturelles Erbe.",
      hu: "Gjümri Örményország második legnagyobb városa, amely híres történelmi építészetéről és gazdag kulturális örökségéről.",
      ro: "Gyumri este al doilea oraș ca mărime din Armenia, faimos pentru arhitectura sa istorică și patrimoniul cultural bogat.",
      en: "Gyumri is the second largest city in Armenia, famous for its historical architecture and rich cultural heritage.",
      es: "Gyumri es la segunda ciudad más grande de Armenia, famosa por su arquitectura histórica y su rico patrimonio cultural.",
      pt: "Gyumri é a segunda maior cidade da Arménia, famosa pela sua arquitetura histórica e rico património cultural.",
      fr: "Gyumri est la deuxième plus grande ville d'Arménie, célèbre pour son architecture historique et son riche patrimoine culturel.",
    },
    descriptionAdvanced: {
      de: "Gjumri ist mit rund 110.000 Einwohnern die zweitgrößte Stadt Armeniens und das kulturelle Herz der nordwestlichen Provinz Schirak in der Achurjan-Hochebene auf etwa 1.550 Metern Höhe. Im 19. Jahrhundert blühte die Stadt unter dem Namen Alexandropol als russische Garnisons- und Handelsstadt auf und entwickelte ein einzigartiges urbanes Ensemble aus schwarzen und roten Tuffstein-Bürgerhäusern, schmiedeeisernen Balkonen, Innenhöfen und neoklassischen Kirchen, von denen viele in den historischen Vierteln Kumayri und um den Vardanants-Platz erhalten geblieben sind. Das schwere Erdbeben vom 7. Dezember 1988 mit der Stärke 6,8 zerstörte große Teile der Stadt und kostete in der Region etwa 25.000 Menschen das Leben; der Wiederaufbau dauert bis heute an. Gjumri gilt als heimliche Hauptstadt des armenischen Humors, der Volksmusik (Aschughen), des Kunsthandwerks und der Schmiedekunst und beherbergt eine weiterhin aktive russische Militärbasis sowie Universitäten, Museen und ein lebendiges Kunstquartier rund um die alte Eisenbahnlinie.",
      hu: "Gjümri Örményország második legnagyobb városa mintegy 110 ezer lakossal, az északnyugati Sirak tartomány kulturális szíve az Ahurjan-fennsíkon, körülbelül 1550 méteres tengerszint feletti magasságban. A 19. században Alekszandropol néven orosz helyőrségi és kereskedővárosként virágzott, és egyedi városi együttest alakított ki: fekete és vörös tufakőből emelt polgárházakat, kovácsoltvas erkélyeket, belső udvarokat és neoklasszikus templomokat, melyek a Kumajri történelmi negyedben és a Vardanantsz tér környékén nagyrészt máig fennmaradtak. Az 1988. december 7-i 6,8-es erősségű földrengés a várost romba döntötte, a régióban közel 25 ezer ember halt meg, és az újjáépítés mindmáig tart. Gjümrit az örmény humor, a népzene (asughok), a kézművesség és a kovácsmesterség titkos fővárosaként emlegetik; a városban máig orosz katonai bázis működik, valamint egyetemek, múzeumok és egy lüktető művészeti negyed a régi vasútvonal mentén.",
      ro: "Gyumri, cu aproximativ 110.000 de locuitori, este al doilea oraș ca mărime al Armeniei și inima culturală a provinciei nord-vestice Șirak, situată pe podișul Ahurian la circa 1.550 de metri altitudine. În secolul al XIX-lea, sub numele de Alexandropol, a înflorit ca oraș-garnizoană și centru comercial al Imperiului Rus, dezvoltând un ansamblu urban unic, format din case burgheze din tuf negru și roșu, balcoane din fier forjat, curți interioare și biserici neoclasice, păstrate în mare parte în cartierul istoric Kumayri și în jurul Pieței Vardanants. Cutremurul devastator din 7 decembrie 1988, de magnitudine 6,8, a distrus orașul și a ucis aproximativ 25.000 de oameni în regiune, iar reconstrucția continuă și astăzi. Gyumri este considerat capitala secretă a umorului armean, a muzicii populare (așughilor), a artizanatului și a fierăriei, și găzduiește încă o bază militară rusă, universități, muzee și un cartier artistic viu de-a lungul vechii linii feroviare.",
      en: "With around 110,000 inhabitants, Gyumri is Armenia's second largest city and the cultural heart of the north-western Shirak Province, sitting on the Akhurian plateau at roughly 1,550 metres altitude. In the 19th century the town flourished as Alexandropol, a Russian garrison and trading hub, developing a unique urban ensemble of merchant houses built from black and red volcanic tuff, wrought-iron balconies, inner courtyards and neoclassical churches, much of it preserved in the historic Kumayri district and around Vardanants Square. The catastrophic earthquake of 7 December 1988 measured 6.8 and killed roughly 25,000 people across the region; rebuilding has continued for decades. Gyumri is regarded as the secret capital of Armenian humour, folk music (the ashughs), handicrafts and ironwork, and still hosts a Russian military base alongside universities, museums and a lively arts quarter along the old railway line.",
      es: "Gyumri, con unos 110.000 habitantes, es el corazón cultural de la provincia de Shirak, situada a 1.550 metros de altitud. En el siglo XIX prosperó como Alexandropol, desarrollando un estilo urbano único con casas de toba negra y roja y balcones de hierro forjado en el barrio de Kumayri. El devastador terremoto de 1988 destruyó gran parte de la ciudad, cuya reconstrucción continúa hoy. Conocida como la capital del humor y la música tradicional armenia, Gyumri alberga universidades, museos y una activa base militar rusa.",
      pt: "Gyumri, com 110.000 habitantes, é o coração cultural da província de Shirak, situada a 1.550 metros de altitude. No século XIX prosperou como Alexandropol, desenvolvendo um conjunto urbano único de casas de tufo preto e vermelho no bairro de Kumayri. O terramoto de 1988 destruiu grande parte da cidade e custou milhares de vidas; a reconstrução ainda prossegue. Gyumri é considerada a capital do humor, da música folclórica e do artesanato arménio, abrigando também uma base militar russa ativa.",
      fr: "Gyumri, avec environ 110 000 habitants, est le cœur culturel de la province de Shirak, située à 1 550 mètres d'altitude. Au XIXe siècle, elle a prospéré sous le nom d'Alexandropol, développant un style urbain unique avec des maisons en tuf noir et rouge dans le quartier de Koumayri. Le séisme de 1988 a détruit une grande partie de la ville ; la reconstruction se poursuit aujourd'hui. Gyumri est considérée comme la capitale de l'humour, de la musique populaire et de l'artisanat, et abrite une base militaire russe active ainsi que des musées.",
    },
