    type: "city",
    parent: "AM-LO",
    coords: [44.4886, 40.8074],
    name: { de: "Wanadsor", hu: "Vanadzor", ro: "Vanadzor", en: "Vanadzor"},
    image: "/poi-images/armenia-vanadzor-cities-v2.webp",
    description: {
      de: "Wanadsor ist eine Industrie- und Kurstadt im Norden Armeniens, umgeben von malerischen Bergen und Wäldern.",
      hu: "Vanadzor egy ipari és üdülőváros Észak-Örményországban, melyet festői hegyek és erdők vesznek körül.",
      ro: "Vanadzor este un oraș industrial și stațiune în nordul Armeniei, înconjurat de munți și păduri pitorești.",
      en: "Vanadzor is an industrial and resort city in northern Armenia, surrounded by picturesque mountains and forests.",
      es: "Vanadzor es una ciudad industrial y balnearia en el norte de Armenia, rodeada de pintorescas montañas y bosques.",
      pt: "Vanadzor é uma cidade industrial e estância termal no norte da Armênia, rodeada por montanhas pitorescas e florestas.",
      fr: "Vanadzor est une ville industrielle et thermale au nord de l'Arménie, entourée de montagnes pittoresques et de forêts.",
    },
    descriptionAdvanced: {
      de: "Wanadsor liegt auf etwa 1.350 Metern Höhe in der Provinz Lori, dort wo die Flüsse Pambak, Tandsut und Wanadsor zusammenfließen, und ist mit rund 75.000 Einwohnern die drittgrößte Stadt Armeniens. Bis 1935 hieß die Siedlung Karakilisa, danach Kirowakan zu Ehren des sowjetischen Funktionärs Sergei Kirow, und erst 1992 wurde sie nach der Unabhängigkeit Armeniens in das altarmenische Wanadsor zurückbenannt. In der Sowjetzeit galt Wanadsor als drittes industrielles Zentrum des Landes mit chemischer Produktion, Textilien und Maschinenbau, doch das Erdbeben von 1988 und der Zusammenbruch der UdSSR trafen die Stadt schwer. Heute ist Wanadsor zugleich Verwaltungs- und Universitätsstadt, Erholungsort mit waldreicher Umgebung, Mineralquellen und mildem Bergklima sowie Ausgangspunkt für Ausflüge ins Debed-Tal mit den UNESCO-Klöstern Haghpat und Sanahin und in den Nationalpark Dilidschan.",
      hu: "Vanadzor Örményország harmadik legnagyobb városa, mintegy 75 ezer lakossal, a Lori tartományban, körülbelül 1350 méter magasan, ott, ahol a Pambak, a Tandzut és a Vanadzor folyók összeérnek. A települést 1935-ig Karakilisának, majd a szovjet funkcionárius Szergej Kirov tiszteletére Kirovakannak hívták, és csak az 1991-es függetlenné válás után, 1992-ben kapta vissza ősi örmény nevét: Vanadzor. A szovjet időszakban a vegyipar, a textilipar és a gépgyártás révén az ország harmadik ipari központja volt, ám az 1988-as földrengés és a Szovjetunió szétesése súlyos csapást mért rá. Ma Vanadzor egyszerre közigazgatási és egyetemi város, üdülőhely is, gazdag erdőkkel, ásványvízforrásokkal és enyhe hegyvidéki éghajlattal, és kiváló kiindulópont a Debed-szurdokba, a haghpati és szanahini UNESCO-kolostorokhoz, valamint a Dilidzsani Nemzeti Parkba tett kirándulásokhoz.",
      ro: "Vanadzor este al treilea oraș ca mărime al Armeniei, cu aproximativ 75.000 de locuitori, situat la circa 1.350 de metri altitudine în provincia Lori, la confluența râurilor Pambak, Tandzut și Vanadzor. Până în 1935 s-a numit Karakilisa, apoi a fost rebotezat Kirovakan în onoarea funcționarului sovietic Serghei Kirov, iar abia după independența din 1991 i s-a redat, în 1992, numele armean vechi de Vanadzor. În perioada sovietică a fost al treilea centru industrial al țării, cu industrie chimică, textilă și constructoare de mașini, însă cutremurul din 1988 și prăbușirea URSS l-au lovit grav. Astăzi Vanadzor este în același timp oraș administrativ și universitar, stațiune climaterică cu păduri întinse, izvoare minerale și climă montană blândă, dar și un punct de plecare excelent pentru excursii în defileul Debed la mănăstirile Haghpat și Sanahin (UNESCO) și în Parcul Național Dilijan.",
      en: "Vanadzor sits at around 1,350 metres above sea level in the Lori Province, where the Pambak, Tandzut and Vanadzor rivers meet, and with about 75,000 inhabitants it is Armenia's third largest city. The settlement was known as Karakilisa until 1935, then renamed Kirovakan in honour of the Soviet functionary Sergei Kirov, and only reverted to its ancient Armenian name Vanadzor in 1992 after independence. In Soviet times the city ranked as the country's third industrial centre, producing chemicals, textiles and machinery, but the 1988 earthquake and the collapse of the USSR hit it hard. Today Vanadzor is at once an administrative and university town and a resort, surrounded by forests, mineral springs and a mild mountain climate, and a great starting point for trips into the Debed gorge with the UNESCO monasteries of Haghpat and Sanahin and into Dilijan National Park.",
      es: "Vanadzor se encuentra a unos 1.350 metros de altitud en la provincia de Lori, en la confluencia de los ríos Pambak, Tandzut y Vanadzor, y es la tercera ciudad más grande de Armenia con unos 75.000 habitantes. Hasta 1935 el asentamiento se llamó Karakilisa, luego Kirovakan en honor al funcionario soviético Serguéi Kírov, y solo en 1992, tras la independencia de Armenia, recuperó su antiguo nombre armenio Vanadzor. En la época soviética, Vanadzor era considerada el tercer centro industrial del país con producción química, textil e ingeniería mecánica, aunque el terremoto de 1988 y el colapso de la URSS afectaron gravemente a la ciudad. Hoy en día, Vanadzor es tanto una ciudad administrativa y universitaria como un lugar de descanso con un entorno boscoso, manantiales minerales y un clima de montaña suave, además de ser punto de partida para excursiones al valle del Debed con los monasterios de Haghpat y Sanahin (UNESCO) y al Parque Nacional Dilijan.",
      pt: "Vanadzor situa-se a cerca de 1.350 metros de altitude na província de Lori, onde os rios Pambak, Tandzut e Vanadzor se encontram, sendo a terceira maior cidade da Armênia com cerca de 75.000 habitantes. Até 1935 o assentamento chamava-se Karakilisa, depois Kirovakan em honra ao funcionário soviético Sergei Kirov, e apenas em 1992, após a independência, foi renomeada para o antigo nome armênio Vanadzor. Na era soviética, Vanadzor era o terceiro centro industrial do país com produção química, têxtil e engenharia, mas o sismo de 1988 e o colapso da URSS atingiram severamente a cidade. Hoje, Vanadzor é simultaneamente uma cidade administrativa e universitária, um local de lazer com arredores arborizados, fontes minerais e clima de montanha suave, servindo de base para excursões ao vale do Debed com os mosteiros UNESCO de Haghpat e Sanahin e ao Parque Nacional Dilijan.",
      fr: "Vanadzor est située à environ 1 350 mètres d'altitude dans la province de Lori, au confluent des rivières Pambak, Tandzut et Vanadzor, et est la troisième plus grande ville d'Arménie avec environ 75 000 habitants. Jusqu'en 1935, l'établissement s'appelait Karakilisa, puis Kirovakan en l'honneur du fonctionnaire soviétique Sergueï Kirov, et ce n'est qu'en 1992, après l'indépendance de l'Arménie, qu'elle a repris son nom arménien ancien de Vanadzor. À l'époque soviétique, Vanadzor était considérée comme le troisième centre industriel du pays avec des productions chimiques, textiles et mécaniques, mais le tremblement de terre de 1988 et l'effondrement de l'URSS ont durement touché la ville. Aujourd'hui, Vanadzor est à la fois une ville administrative et universitaire, un lieu de villégiature avec un environnement boisé, des sources minérales et un climat de montagne doux, ainsi qu'un point de départ pour des excursions dans la vallée du Debed avec les monastères UNESCO de Haghpat et Sanahin et le parc national de Dilidjan.",
    },
