    coords: [44.6264, 40.2747],
    name: { de: "Abowjan", hu: "Abovjan", ro: "Abovian", en: "Abovyan"},
    image: "/poi-images/armenia-abovyan-cities-v2.webp",
    description: {
      de: "Abowjan ist eine moderne Industriestadt nördlich von Erivan, die als wichtige Satellitenstadt dient.",
      hu: "Abovjan egy modern iparváros Jerevántól északra, amely fontos szatellitvárosként szolgál.",
      ro: "Abovian este un oraș industrial modern situat la nord de Erevan, servind drept un oraș-satelit major.",
      en: "Abovyan is a modern industrial city located just north of Yerevan, serving as a major satellite town.",
      es: "Abovyan es una ciudad industrial moderna al norte de Ereván que sirve como una importante ciudad satélite.",
      pt: "Abovyan é uma cidade industrial moderna ao norte de Erevan, que serve como uma importante cidade satélite.",
      fr: "Abovyan est une ville industrielle moderne au nord d'Erevan, servant de ville satellite importante.",
    },
    descriptionAdvanced: {
      de: "Abowjan liegt nur etwa 16 Kilometer nordöstlich von Eriwan auf einer Höhe von rund 1.400 Metern in der Provinz Kotajk und gilt als jüngste größere Stadt Armeniens. Sie entstand 1963 durch Vereinigung mehrerer Dörfer rund um Elar und wurde als sozialistische Planstadt für rund 50.000 Einwohner konzipiert, mit breiten Achsen, Mikrorajons aus typischen Plattenbauten, einer großzügigen Grünausstattung und mehreren Industriebetrieben für Maschinenbau, Chemie, Lichttechnik und Baustoffe. Namensgeber ist Chatschatur Abowjan, der bedeutende Schriftsteller und Bildungsreformer des 19. Jahrhunderts, dessen unvollendetes Verschwinden 1848 bis heute Mythen anregt. Nach dem Zerfall der UdSSR brach der Großteil der Industrie zusammen, doch dank der Nähe zur Hauptstadt entwickelte sich Abowjan zu einer wichtigen Schlafstadt mit modernen Logistikzentren, einer Eisenbahnverbindung nach Sewan und einem zunehmenden IT- und Handelssektor; in der Umgebung liegen die Festung Bdschni, das Kloster Geghard und der Garni-Tempel.",
      hu: "Abovjan Jerevántól mindössze 16 kilométerre északkeletre, mintegy 1400 méter magasan helyezkedik el a Kotajk tartományban, és Örményország egyik legfiatalabb nagyobb városa. 1963-ban hozták létre, az Elar környéki falvak egyesítésével, és kifejezetten szocialista tervvárosnak szánták, körülbelül 50 ezer lakosra méretezve, széles tengelyekkel, panelházakból álló mikrorajonokkal, bőséges zöldfelülettel és gépipari, vegyipari, világítástechnikai, valamint építőanyag-üzemekkel. Nevét a 19. század kiemelkedő írójáról és oktatási reformeréről, Hacsatur Abovjanról kapta, akinek 1848-as rejtélyes eltűnése máig mítoszokat sző. A Szovjetunió szétesése után az ipar nagy része összeomlott, de a főváros közelsége miatt Abovjan fontos alvóvárossá fejlődött, modern logisztikai központokkal, Szeván felé tartó vasútvonallal, valamint egyre erősebb informatikai és kereskedelmi szektorral; környékén található a bdzsni erőd, a gegárdi sziklakolostor és a garnii pogány templom.",
      ro: "Abovian se află la doar 16 km nord-est de Erevan, la circa 1.400 de metri altitudine, în provincia Kotaik, și este unul dintre cele mai tinere orașe mari ale Armeniei. A fost creat în 1963 prin unirea mai multor sate din jurul localității Elar și conceput ca oraș-planificat socialist pentru aproximativ 50.000 de locuitori, cu axe largi, cartiere-microraioane din blocuri-tip, multe spații verzi și mai multe uzine de mașini, chimie, iluminat și materiale de construcții. Numele îi vine de la Haciatur Abovian, marele scriitor și reformator al educației din secolul al XIX-lea, a cărui dispariție misterioasă din 1848 alimentează legende până astăzi. După destrămarea URSS, mare parte din industrie s-a prăbușit, dar apropierea de capitală a transformat Abovianul într-un important oraș-dormitor, cu centre logistice moderne, o linie de cale ferată spre Sevan și un sector IT și comercial în creștere; în împrejurimi se află cetatea Bjni, mănăstirea Gheghard și templul de la Garni.",
      en: "Abovyan lies just 16 km north-east of Yerevan at around 1,400 metres altitude in the Kotayk Province and is one of Armenia's youngest sizeable cities. It was formed in 1963 by merging several villages around Elar and designed as a socialist planned town for some 50,000 inhabitants, with broad axes, microdistricts of standard panel blocks, generous green areas and a string of plants for machinery, chemicals, lighting and building materials. The town is named after Khachatur Abovian, the great 19th-century writer and education reformer whose mysterious disappearance in 1848 still inspires legends. After the collapse of the USSR much of the industry shut down, but proximity to the capital turned Abovyan into a major commuter city with modern logistics hubs, a railway towards Lake Sevan and a growing IT and retail sector; nearby attractions include Bjni fortress, Geghard cave monastery and the pagan temple of Garni.",
      es: "Abovyan se encuentra a solo 16 kilómetros al noreste de Ereván, a unos 1.400 metros de altitud en la provincia de Kotayk, y es considerada la ciudad importante más joven de Armenia. Fue creada en 1963 mediante la unión de varios pueblos alrededor de Elar y concebida como una ciudad planificada socialista para unos 50.000 habitantes, con amplios ejes, barrios típicos de bloques de hormigón, abundantes zonas verdes y diversas industrias. Lleva el nombre de Khachatur Abovyan, el gran escritor y reformador educativo del siglo XIX, cuya desaparición en 1848 sigue alimentando mitos. Tras el colapso de la URSS, gran parte de la industria decayó, pero gracias a su cercanía a la capital, Abovyan se transformó en una importante ciudad dormitorio con centros logísticos modernos y un sector comercial y de TI en crecimiento.",
      pt: "Abovyan situa-se a apenas cerca de 16 quilómetros a nordeste de Erevan, a uma altitude de cerca de 1.400 metros na província de Kotayk, e é considerada a cidade grande mais jovem da Arménia. Criada em 1963 pela união de várias aldeias em redor de Elar, foi concebida como uma cidade planeada socialista para cerca de 50.000 habitantes, com eixos largos, microrajons de blocos de betão típicos, espaços verdes generosos e várias empresas industriais. O nome é uma homenagem a Khachatur Abovyan, o importante escritor e reformador educacional do século XIX, cujo desaparecimento inacabado em 1848 ainda hoje desperta mitos. Após a queda da URSS, a maior parte da indústria colapsou, mas graças à proximidade com a capital, Abovyan tornou-se uma importante cidade-dormitório com centros logísticos modernos e um setor comercial e de TI crescente.",
      fr: "Abovyan se trouve à seulement 16 kilomètres au nord-est d'Erevan, à une altitude d'environ 1 400 mètres dans la province de Kotayk, et est considérée comme la plus jeune grande ville d'Arménie. Créée en 1963 par l'union de plusieurs villages autour d'Elar, elle a été conçue comme une ville nouvelle socialiste pour environ 50 000 habitants, avec de larges axes, des quartiers d'immeubles typiques, de nombreux espaces verts et plusieurs usines industrielles. Elle porte le nom de Khatchatour Abovian, l'écrivain et réformateur de l'éducation du XIXe siècle, dont la disparition inexpliquée en 1848 alimente encore les mythes. Après l'effondrement de l'URSS, l'industrie a décliné, mais grâce à sa proximité avec la capitale, Abovyan est devenue une ville-dortoir majeure dotée de centres logistiques modernes et d'un secteur commercial et informatique en pleine croissance.",
    },
