      hu: ["A várost hivatalosan 1963-ban alapították.", "Az Elar területén végzett ásatások a bronzkorig nyúlnak vissza.", "A település 1450 méter tengerszint feletti magasságon fekszik.", "A Szent János-templom (Szurb Hovhannesz) a város modern jelképe.", "A városban jelentős precíziós műszergyártás folyik.", "Örményország egyik legjobban megtervezett szovjet korszakbeli városa."],
      ro: ["Orașul a fost fondat oficial în anul 1963.", "Descoperirile arheologice din zona Elar datează din epoca bronzului.", "Abovyan este situat la o altitudine de aproximativ 1.450 de metri.", "Biserica Sfântul Ioan (Surb Hovhannes) este un reper arhitectural modern.", "Orașul găzduiește fabrici importante de mecanică de precizie.", "Este considerat unul dintre cele mai bine planificate orașe din era sovietică."],
      en: ["The city was officially established in 1963.", "Archaeological findings in Elar date back to the Bronze Age.", "Abovyan is situated at an elevation of about 1,450 meters.", "Saint John the Baptist Church (Surb Hovhannes) is a prominent modern landmark.", "The city is known for its precision engineering and electronic industries.", "It is regarded as one of the best-planned Soviet-era cities in Armenia."],
      es: ["La ciudad fue fundada oficialmente en el año 1963.", "Los hallazgos arqueológicos en Elar se remontan a la Edad del Bronce.", "Abovyan se encuentra a una altitud de unos 1.450 metros.", "La iglesia de San Juan (Surb Hovhannes) es un hito moderno de la ciudad.", "Existen importantes empresas de mecánica de precisión en la ciudad.", "Es considerada una de las ciudades mejor planificadas de la era soviética en Armenia."],
      pt: ["A cidade foi fundada oficialmente no ano de 1963.", "Achados arqueológicos em Elar remontam à Idade do Bronze.", "Abovyan situa-se a uma altitude de cerca de 1.450 metros.", "A Igreja de São João (Surb Hovhannes) é um marco moderno da cidade.", "Existem empresas significativas de mecânica de precisão na cidade.", "É considerada uma das cidades melhor planeadas da era soviética na Arménia."],
      fr: ["La ville a été officiellement fondée en 1963.", "Les découvertes archéologiques à Elar remontent à l'âge du bronze.", "Abovyan est située à une altitude d'environ 1 450 mètres.", "L'église Saint-Jean (Surb Hovhannes) est un monument moderne de la ville.", "La ville abrite d'importantes entreprises de mécanique de précision.", "Considérée comme l'une des villes les mieux planifiées de l'ère soviétique en Arménie."],
