    coords: [44.0375, 40.1558],
    name: { de: "Armawir", hu: "Armavir", ro: "Armavir", en: "Armavir"},
    image: "/poi-images/armenia-armavir-cities-v2.webp",
    description: {
      de: "Armawir ist eine alte Stadt, die einst eine der historischen Hauptstädte Armeniens war und heute ein modernes Verwaltungszentrum ist.",
      hu: "Armavir egy ősi város, amely egykor Örményország egyik történelmi fővárosa volt, ma pedig modern közigazgatási központ.",
      ro: "Armavir este un oraș antic care a servit drept una dintre capitalele istorice ale Armeniei, acum un centru administrativ modern.",
      en: "Armavir is an ancient city that served as one of the historical capitals of Armenia, now a modern administrative center.",
      es: "Armavir es una ciudad antigua que una vez fue una de las capitales históricas de Armenia y hoy es un centro administrativo moderno.",
      pt: "Armavir é uma cidade antiga que outrora foi uma das capitais históricas da Arménia e que hoje é um moderno centro administrativo.",
      fr: "Armavir est une ville ancienne qui fut autrefois l'une des capitales historiques de l'Arménie et qui est aujourd'hui un centre administratif moderne.",
    },
    descriptionAdvanced: {
      de: "Armawir liegt rund 50 Kilometer westlich von Eriwan in der fruchtbaren Ararat-Ebene auf etwa 870 Metern Höhe und ist Hauptstadt der gleichnamigen Provinz mit rund 30.000 Einwohnern. Die Stadt trägt den Namen einer der antiken Hauptstädte Armeniens: das ursprüngliche Armawir lag etwa 8 Kilometer entfernt und war im 8. Jahrhundert v. Chr. eine urartäische Festung, später von der Dynastie der Orontiden zur Hauptstadt erhoben und blieb bis ins 2. Jahrhundert v. Chr. wichtigster Verwaltungssitz. Die heutige Stadt entstand erst 1931 als Sowchos-Siedlung und hieß bis 1995 Hoktemberjan („Oktoberstadt“), bevor sie den historischen Namen Armawir erhielt. Sie ist umgeben von ausgedehnten Obst- und Weingärten, Aprikosen-, Pfirsich- und Granatapfelplantagen sowie Bewässerungskanälen aus der Sowjetzeit. Wirtschaftlich dominieren Wein- und Konservenfabriken, Tomatenmark- und Käseproduktion sowie zunehmend Solarenergie; Armawir ist außerdem Knotenpunkt der Straßen- und Bahnverbindung Eriwan – Türkei (über die geschlossene Grenze).",
      hu: "Armavir Jerevántól mintegy 50 kilométerre nyugatra, az Ararát-síkság termékeny részén, körülbelül 870 méter magasan fekszik, és az azonos nevű tartomány fővárosa, mintegy 30 ezer lakossal. A város Örményország egyik ókori fővárosának nevét viseli: az eredeti Armavir mintegy 8 kilométerre, Krisztus előtt a 8. században urartui erődként jött létre, később az Orontida-dinasztia alatt vált fővárossá, és Krisztus előtt a 2. századig maradt fontos közigazgatási központ. A mai város csupán 1931-ben jött létre szovhozközpontként, és 1995-ig Hoktemberjan („Október-város”) néven szerepelt, csak ezután kapta vissza az ősi Armavir nevet. A települést hatalmas gyümölcsöskertek, sárgabarack-, őszibarack- és gránátalma-ültetvények, valamint a szovjet időkből származó öntözőcsatornák veszik körül. Gazdaságát bor- és konzervgyárak, paradicsompüré- és sajtkészítés, valamint egyre inkább a napenergia uralja; Armavir egyben a Jerevánból a (lezárt) török határ felé vezető közúti és vasúti csomópont is.",
      ro: "Armavir se află la aproximativ 50 km vest de Erevan, în partea fertilă a câmpiei Ararat, la circa 870 de metri altitudine, și este capitala provinciei cu același nume, cu aproximativ 30.000 de locuitori. Orașul poartă numele uneia dintre vechile capitale ale Armeniei: vechiul Armavir se afla la circa 8 km depărtare, era în secolul al VIII-lea î.Hr. o fortăreață urartiană și a devenit ulterior, sub dinastia Orontidă, capitală a regatului armean, păstrându-și rolul administrativ până în secolul al II-lea î.Hr. Orașul actual a apărut abia în 1931 ca centru de sovhoz și s-a numit până în 1995 Hoktemberian („Orașul lui Octombrie”), când i s-a redat numele istoric Armavir. Localitatea este înconjurată de livezi întinse de fructe, plantații de caise, piersici și rodii și canale de irigații din epoca sovietică. Economia este dominată de fabrici de vin și conserve, de producția de pastă de tomate și de brânzeturi, dar și, tot mai mult, de energia solară; Armavir este, de asemenea, un nod rutier și feroviar pe ruta Erevan – frontiera turcă (închisă).",
      en: "Armavir lies about 50 km west of Yerevan in the fertile Ararat plain at roughly 870 metres altitude and is the capital of the province of the same name, home to around 30,000 inhabitants. The town carries the name of one of ancient Armenia's capitals: the original Armavir lay some 8 km away and was an Urartian fortress in the 8th century BC, later raised to the status of capital by the Orontid dynasty and remained an important administrative seat until the 2nd century BC. The modern town was only founded in 1931 as the centre of a sovkhoz and was called Hoktemberyan ('October Town') until 1995, when its historical name was restored. The settlement is surrounded by vast orchards, plantations of apricots, peaches and pomegranates and Soviet-era irrigation canals. Its economy is dominated by wine and canning factories, tomato paste and cheese production and, increasingly, solar power; Armavir is also a road and rail junction on the route from Yerevan towards the (closed) Turkish border.",
      es: "Armavir se encuentra a unos 50 kilómetros al oeste de Ereván, en la fértil llanura de Ararat, y es la capital de la provincia homónima con unos 30.000 habitantes. La ciudad lleva el nombre de una antigua capital armenia situada a 8 kilómetros, que fue una fortaleza urartiana en el siglo VIII a.C. La ciudad actual surgió en 1931 como un asentamiento soviético llamado Hoktemberyan hasta 1995. Está rodeada de extensos huertos y viñedos, con plantaciones de albaricoques, melocotones y granadas regadas por canales de la era soviética. Económicamente, predominan las fábricas de vino y conservas, la producción de queso y, cada vez más, la energía solar; además, es un nudo de transporte hacia Turquía (aunque la frontera permanece cerrada).",
      pt: "Armavir situa-se a cerca de 50 quilómetros a oeste de Erevan, na fértil planície de Ararat, e é a capital da província com o mesmo nome, com cerca de 30.000 habitantes. A cidade tem o nome de uma das antigas capitais da Arménia: a Armavir original ficava a cerca de 8 quilómetros de distância e era uma fortaleza urartiana no século VIII a.C. A cidade atual surgiu apenas em 1931 como um assentamento sovchoz e chamou-se Hoktemberyan até 1995. Está rodeada por extensos pomares e vinhedos, plantações de damascos, pêssegos e romãs, bem como canais de irrigação da era soviética. Economicamente, dominam as fábricas de vinho e conservas, bem como a produção de queijo e, cada vez mais, a energia solar.",
      fr: "Armavir se trouve à environ 50 kilomètres à l'ouest d'Erevan, dans la fertile plaine de l'Ararat, et est la capitale de la province du même nom avec environ 30 000 habitants. La ville porte le nom de l'une des anciennes capitales de l'Arménie : l'Armavir originelle se trouvait à environ 8 kilomètres et était une forteresse urartéenne au VIIIe siècle av. J.-C. La ville actuelle est née en 1931 en tant que colonie de sovkhoze et s'est appelée Hoktemberyan jusqu'en 1995. Elle est entourée de vastes vergers et vignobles, de plantations d'abricots, de pêches et de grenades. Sur le plan économique, les usines de vin et de conserves dominent, ainsi que la production de fromage et, de plus en plus, l'énergie solaire.",
    },
