      en: ["The modern city was officially established in 1931.", "Ancient Armavir was mentioned as a capital as early as the 4th century BC.", "Armavir is situated at an elevation of about 870 meters.", "The surrounding region is Armenia's primary agricultural center.", "The Sardarapat Memorial is located approximately 10 kilometers away.", "The city was renamed from Hoktemberyan to Armavir in 1995."],
      es: ["La ciudad moderna fue fundada oficialmente en el año 1931.", "La antigua ciudad de Armavir ya fue mencionada en el siglo IV a.C.", "Armavir se encuentra a una altitud de unos 870 metros.", "La región es el centro agrícola más importante de Armenia.", "El monumento de Sardarapat se encuentra a unos 10 kilómetros.", "La ciudad fue renombrada en 1995 en honor a la antigua capital."],
      pt: ["A cidade moderna foi oficialmente fundada no ano de 1931.", "A antiga cidade de Armavir já era mencionada no século IV a.C.", "Armavir situa-se a uma altitude de cerca de 870 metros.", "A região é o centro agrícola mais importante da Arménia.", "O monumento de Sardarapat localiza-se a cerca de 10 quilómetros.", "A cidade foi renomeada em 1995 em homenagem à antiga capital."],
      fr: ["La ville moderne a été officiellement fondée en 1931.", "L'ancienne cité d'Armavir était déjà mentionnée au IVe siècle av. J.-C.", "Armavir est située à une altitude d'environ 870 mètres.", "La région est le principal centre agricole d'Arménie.", "Le monument de Sardarapat se trouve à environ 10 kilomètres.", "La ville a été renommée en 1995 d'après l'ancienne capitale."],
