    coords: [44.5458, 39.9614],
    name: { de: "Artaschat", hu: "Artasat", ro: "Artașat", en: "Artashat"},
    image: "/poi-images/armenia-artashat-cities-v2.webp",
    description: {
      de: "Artaschat ist die Hauptstadt der Provinz Ararat, erbaut in der Nähe der Ruinen der gleichnamigen antiken armenischen Hauptstadt.",
      hu: "Artasat az Ararát tartomány fővárosa, amelyet az azonos nevű ősi örmény főváros romjai közelében építettek.",
      ro: "Artașat este capitala provinciei Ararat, construită lângă ruinele vechii capitale armene cu același nume.",
      en: "Artashat is the capital of the Ararat Province, built near the ruins of the ancient Armenian capital of the same name.",
      es: "Artashat es la capital de la provincia de Ararat, construida cerca de las ruinas de la antigua capital armenia del mismo nombre.",
      pt: "Artashat é a capital da província de Ararat, construída perto das ruínas da antiga capital arménia homónima.",
      fr: "Artachat est la capitale de la province d'Ararat, construite à proximité des ruines de l'ancienne capitale arménienne du même nom.",
    },
    descriptionAdvanced: {
      de: "Artaschat liegt etwa 30 Kilometer südlich von Eriwan in der Ararat-Ebene auf rund 830 Metern Höhe und ist Hauptstadt der Provinz Ararat. Die heutige Stadt mit etwa 22.000 Einwohnern entstand 1945 als sowjetische Plansiedlung in der Nähe der Ruinen des antiken Artaschat, das König Artasches I. um 176 v. Chr. der Überlieferung nach mit Beratung des aus Karthago geflüchteten Hannibal gründete. Das alte Artaschat lag auf zwölf Hügeln am Zusammenfluss von Araxes und Mezamor, war jahrhundertelang Hauptstadt Armeniens, ein Dreh- und Angelpunkt der Seidenstraße und galt als „armenisches Karthago“. Auf einem dieser Hügel, Khor Virap, stand zugleich der Kerker, in den König Trdat den heiligen Gregor den Erleuchter 13 Jahre lang einsperrte – heute ist das gleichnamige Kloster mit dem unvergleichlichen Blick auf den Berg Ararat ein Hauptpilgerziel. Die moderne Stadt lebt von Wein- und Kognakproduktion, Konservenindustrie, Bewässerungslandwirtschaft und Tourismus rund um die archäologische Zone und Khor Virap.",
      hu: "Artasat Jerevántól mintegy 30 kilométerre délre, az Ararát-síkságon, körülbelül 830 méter magasan fekszik, és az Ararát tartomány fővárosa. A mai, mintegy 22 ezer lakosú város 1945-ben jött létre szovjet tervtelepülésként, az ókori Artasat romjai közelében, amelyet I. Artases király Krisztus előtt 176 körül a hagyomány szerint a Karthágóból menekült Hannibál tanácsára alapított. A régi Artasat tizenkét dombon állt, az Arax és a Mecamor összefolyásánál, évszázadokon át volt Örményország fővárosa, a selyemút egyik fontos csomópontja, és „örmény Karthágóként” emlegették. Az egyik dombon, Hor Virapon állt az a tömlöc is, amelybe Trdat király tizenhárom évre bezáratta Világosító Szent Gergelyt – ma az ott álló kolostor a Hor Virap, az Ararát-hegyre nyíló páratlan kilátással, az ország egyik legfőbb zarándokhelye. A modern város bortermelésből, konyakgyártásból, konzervgyártásból, öntözött mezőgazdaságból és a régészeti zóna, valamint Hor Virap idegenforgalmából él.",
      ro: "Artașat se află la circa 30 km sud de Erevan, în câmpia Ararat, la aproximativ 830 de metri altitudine, și este capitala provinciei Ararat. Orașul actual, cu aproximativ 22.000 de locuitori, a fost creat în 1945 ca așezare sovietică planificată, în apropierea ruinelor vechiului Artașat, fondat în jurul anului 176 î.Hr. de regele Artașes I, conform tradiției cu sfatul lui Hannibal, refugiat aici după prăbușirea Cartaginei. Vechiul Artașat se întindea pe douăsprezece coline la confluența râurilor Araxes și Mețamor, a fost timp de secole capitala Armeniei și un nod important al Drumului Mătăsii, supranumit „Cartagina armeană”. Pe una dintre aceste coline, Khor Virap, se afla și temnița în care regele Trdat l-a închis pe Sfântul Grigore Luminătorul timp de treisprezece ani; mănăstirea actuală cu același nume, cu o priveliște unică spre Muntele Ararat, este astăzi unul dintre cele mai importante locuri de pelerinaj. Orașul modern trăiește din producția de vin și coniac, conserve, agricultură irigată și turismul legat de zona arheologică și de Khor Virap.",
      en: "Artashat lies about 30 km south of Yerevan on the Ararat plain at around 830 metres altitude and is the capital of the Ararat Province. The present-day town of some 22,000 inhabitants was laid out in 1945 as a Soviet planned settlement near the ruins of ancient Artashat, founded around 176 BC by King Artashes I, who according to tradition was advised in his choice of site by the Carthaginian general Hannibal, in exile here after the fall of Carthage. The old city sprawled over twelve hills at the confluence of the Araxes and Metsamor rivers, served for centuries as Armenia's capital and a key Silk Road hub, and was nicknamed the 'Armenian Carthage'. On one of these hills, Khor Virap, stood the dungeon where King Trdat imprisoned Saint Gregory the Illuminator for thirteen years; the monastery of the same name, with its unrivalled view of Mount Ararat, is now one of the country's most important pilgrimage sites. The modern town lives from wine and brandy, canning industries, irrigated agriculture and tourism around the archaeological zone and Khor Virap.",
      es: "Artashat se encuentra a unos 30 kilómetros al sur de Ereván, en la llanura de Ararat a 830 metros de altitud, y es la capital de la provincia de Ararat. La ciudad actual, de unos 22.000 habitantes, surgió en 1945 como un asentamiento soviético cerca de las ruinas de la antigua Artaxata, fundada hacia el 176 a. C. por el rey Artaxias I, según la tradición con el consejo de Aníbal. La antigua capital era un centro estratégico de la Ruta de la Seda y era conocida como la \"Cartago armenia\". En una de sus colinas se encuentra el monasterio de Khor Virap, donde San Gregorio el Iluminador estuvo prisionero, y que hoy ofrece vistas espectaculares del monte Ararat. La economía local se basa en la producción de vino y coñac, la industria conservera y el turismo arqueológico.",
      pt: "Artashat situa-se a cerca de 30 quilómetros a sul de Erevan, na planície de Ararat, a 830 metros de altitude, sendo a capital da província de Ararat. A cidade atual, com cerca de 22.000 habitantes, foi criada em 1945 como um assentamento planeado soviético perto das ruínas da antiga Artaxata, fundada por volta de 176 a.C. pelo rei Artaxias I, supostamente com o conselho de Aníbal. A antiga capital era um ponto fulcral da Rota da Seda e era apelidada de \"Cartago arménia\". Numa destas colinas encontra-se o mosteiro de Khor Virap, onde São Gregório, o Iluminador, esteve preso, sendo hoje um importante local de peregrinação com vistas para o Monte Ararat. A cidade moderna vive da produção de vinho e conhaque, da indústria conserveira e do turismo em redor da zona arqueológica.",
      fr: "Artachat se trouve à environ 30 kilomètres au sud d'Erevan, dans la plaine de l'Ararat, à 830 mètres d'altitude, et est la capitale de la province d'Ararat. La ville actuelle d'environ 22 000 habitants a été créée en 1945 en tant que colonie planifiée soviétique à proximité des ruines de l'ancienne Artaxata, fondée vers 176 av. J.-C. par le roi Artaxias Ier, conseillé selon la tradition par Hannibal. L'ancienne capitale était un carrefour de la Route de la Soie et était considérée comme la « Carthage arménienne ». Sur l'une de ses collines s'élève le monastère de Khor Virap, où Saint Grégoire l'Illuminateur fut emprisonné, offrant aujourd'hui une vue imprenable sur le mont Ararat. La ville moderne vit de la production de vin et de cognac, de l'industrie de la conserve et du tourisme lié à la zone archéologique.",
    },
