    name: { de: "Gawar", hu: "Gavar", ro: "Gavar", en: "Gavar"},
    image: "/poi-images/armenia-gavar-cities-v2.webp",
    description: {
      de: "Gawar ist eine Bergstadt in der Nähe des Sewansees, bekannt für ihre kalten Winter und historischen Denkmäler.",
      hu: "Gavar egy hegyvidéki város a Szeván-tó közelében, mely hideg teleiről és történelmi műemlékeiről ismert.",
      ro: "Gavar este un oraș de munte situat lângă Lacul Sevan, cunoscut pentru iernile sale reci și monumentele istorice.",
      en: "Gavar is a mountainous city located near Lake Sevan, known for its cold winters and historical monuments.",
      es: "Gavar es una ciudad de montaña cerca del lago Seván, conocida por sus inviernos fríos y sus monumentos históricos.",
      pt: "Gavar é uma cidade de montanha perto do lago Sevan, conhecida pelos seus invernos frios e monumentos históricos.",
      fr: "Gavar est une ville de montagne près du lac Sevan, connue pour ses hivers froids et ses monuments historiques.",
    },
    descriptionAdvanced: {
      de: "Gawar ist mit rund 20.000 Einwohnern Hauptstadt der Provinz Gegharkunik und liegt auf einer Höhe von etwa 1.980 Metern, nur wenige Kilometer westlich des Sewansees. Die Stadt entstand im 19. Jahrhundert, als russische Behörden hier Pontosgriechen aus der Region Trabzon und westarmenische Familien aus Bayazet ansiedelten; bis 1959 hieß sie Nor Bayazet (Neu-Bayazet), danach Kamo nach dem bolschewistischen Kämpfer Ter-Petrosjan, und seit 1996 trägt sie wieder ihren altarmenischen Namen Gawar. Geprägt wird das Stadtbild von niedrigen Häusern aus dunklem Basalt, mehreren orthodoxen Kirchen aus der griechischen Zeit und der weiträumigen, oft kalten und windigen Hochebene. Gawar ist Verwaltungs- und Marktzentrum der Region, mit Lebensmittel-, Holz- und Lederindustrie sowie einer Universität, und Ausgangspunkt zu den Sewan-Kreuzsteinfeldern von Noratus, zur archäologischen Zone Lchaschen und zu Wandertouren ins Geghama-Gebirge.",
      hu: "Gavar mintegy 20 ezer lakosú város, a Geharkunik tartomány fővárosa, körülbelül 1980 méter tengerszint feletti magasságban, a Szeván-tótól pár kilométerre nyugatra. A 19. században jött létre, amikor az orosz hatóságok pontoszi görögöket telepítettek ide a Trabzon környékéről, valamint nyugat-örmény családokat Bayazetből; a település 1959-ig a Nor Bayazet (Új-Bayazet) nevet viselte, majd a bolsevik harcos Ter-Petroszjan tiszteletére Kamóra változtatták, és csak 1996 óta kapta vissza az ősi örmény Gavar nevet. Városképét sötét bazaltból emelt, alacsony házak, a görög időkből megmaradt ortodox templomok és a nyitott, gyakran hideg és szeles fennsík határozza meg. Gavar a régió közigazgatási és piaci központja, élelmiszer-, fa- és bőripari üzemekkel, valamint saját egyetemmel, és kiindulópont a noraduzi középkori keresztkőtemető, a lcaseni régészeti zóna és a Geham-hegységbe induló túrák felé.",
      ro: "Gavar, oraș cu aproximativ 20.000 de locuitori, este capitala provinciei Gegharkunik și se află la circa 1.980 de metri altitudine, la doar câțiva kilometri vest de Lacul Sevan. Localitatea a apărut în secolul al XIX-lea, când autoritățile țariste au colonizat aici greci pontici din regiunea Trabzon și familii armene refugiate din Bayazet; orașul s-a numit Nor Bayazet (Noul Bayazet) până în 1959, apoi a fost rebotezat Kamo, după revoluționarul bolșevic Ter-Petrosian, iar din 1996 a revenit la numele său armean vechi de Gavar. Aspectul urban este definit de case scunde din bazalt închis la culoare, de mai multe biserici ortodoxe rămase din perioada greacă și de podișul larg, adesea rece și bătut de vânt. Gavar este centrul administrativ și de piață al regiunii, cu industrie alimentară, prelucrarea lemnului și pielăriei și o universitate proprie, și constituie punctul de plecare spre cimitirul de cruci de piatră de la Noraduz, spre situl arheologic Lchașen și spre traseele Munților Gegham.",
      en: "Gavar, with about 20,000 inhabitants, is the capital of Gegharkunik Province, sitting at roughly 1,980 metres above sea level just a few kilometres west of Lake Sevan. The town arose in the 19th century, when Russian authorities resettled Pontic Greeks from the region around Trabzon and Western Armenian families from Bayazet here; it was called Nor Bayazet (New Bayazet) until 1959, then renamed Kamo after the Bolshevik militant Ter-Petrosyan, and finally restored to its ancient Armenian name Gavar in 1996. Its low houses of dark basalt, several Orthodox churches surviving from the Greek period and the wide, often cold and windy plateau give the place a distinctive character. Gavar is the administrative and market centre of the region, with food, wood and leather industries and its own university, and is the starting point for trips to the medieval cross-stone field of Noratus, the archaeological zone of Lchashen and hiking routes into the Geghama Mountains.",
      es: "Gavar, con unos 20.000 habitantes, es la capital de la provincia de Gegharkunik y se encuentra a 1.980 metros de altitud, cerca del lago Seván. La ciudad fue fundada en el siglo XIX por griegos del Ponto y armenios de Bayaceto; anteriormente se llamó Nor Bayaceto y Kamo. Su paisaje urbano se caracteriza por casas de basalto oscuro e iglesias ortodoxas. Gavar es el centro administrativo de la región y la puerta de entrada al famoso campo de jachkares de Noratus y a las montañas de Geghama.",
      pt: "Gavar, com cerca de 20.000 habitantes, é a capital da província de Gegharkunik e situa-se a 1.980 metros de altitude, perto do lago Sevan. A cidade surgiu no século XIX com a fixação de gregos do Ponto e arménios de Bayazet; chamou-se Nor Bayazet e Kamo antes de recuperar o nome Gavar. O cenário urbano é marcado por casas de basalto escuro e igrejas ortodoxas. É um centro administrativo e o ponto de partida para o campo de khachkars de Noratus e as montanhas de Geghama.",
      fr: "Gavar, avec environ 20 000 habitants, est la capitale de la province de Gegharkounik et se situe à 1 980 mètres d'altitude, près du lac Sevan. La ville a été fondée au XIXe siècle par des Grecs du Pont et des Arméniens de Bayazet ; elle s'est appelée Nor Bayazet puis Kamo. L'architecture est marquée par des maisons en basalte sombre et des églises orthodoxes. Gavar est le centre administratif de la région et le point de départ vers les célèbres khatchkars de Noratus et les montagnes de Geghama.",
    },
