    name: { de: "Goris", hu: "Goris", ro: "Goris", en: "Goris"},
    image: "/poi-images/armenia-goris-cities-v2.webp",
    description: {
      de: "Goris ist berühmt für seinen gitterförmigen Straßenplan und die umliegenden Höhlenwohnungen, die in den weichen Fels gehauen wurden.",
      hu: "Goris híres rácsos utcaszerkezetéről és a puha sziklákba vájt környező barlanglakásairól.",
      ro: "Goris este faimos pentru planul său stradal în grilă și locuințele rupestre din jur, sculptate în roca moale.",
      en: "Goris is famous for its grid street plan and surrounding cave dwellings carved into the soft rock.",
      es: "Goris es famosa por su trazado de calles en forma de cuadrícula y las cuevas habitadas de los alrededores, talladas en la roca blanda.",
      pt: "Goris é famosa pelo seu plano de ruas em grelha e pelas habitações em cavernas nos arredores, esculpidas na rocha macia.",
      fr: "Goris est célèbre pour son plan de rues en damier et les habitations troglodytiques environnantes, taillées dans la roche tendre.",
    },
    descriptionAdvanced: {
      de: "Goris liegt auf rund 1.385 Metern Höhe in einem Talkessel des Flusses Goris in der südlichen Provinz Sjunik, etwa 240 Kilometer südöstlich von Eriwan, und gilt mit seinen rund 20.000 Einwohnern als eine der schönsten Kleinstädte Armeniens. Die heutige Stadt wurde 1870 nach einem klaren rechtwinkligen Stadtplan eines deutschen Architekten neu angelegt; charakteristisch sind zweistöckige Bürgerhäuser aus rohem Stein mit Holzbalkonen, kleine Innenhöfe mit Weinreben und Maulbeerbäumen sowie der breite Mashtots-Boulevard. Vor allem aber ist Goris berühmt für seine surrealen Tuffstein-Pyramiden („steinerne Wälder“) und die uralten Höhlenwohnungen des nahegelegenen Dorfes Khndzoresk, die teilweise bis ins 20. Jahrhundert hinein bewohnt waren und durch eine moderne 160 Meter lange Hängebrücke verbunden sind. Goris ist letzter armenischer Halt an der Strategischen Straße nach Berg-Karabach (Stepanakert), Zentrum für Maulbeerschnaps („mulberry vodka“) und Tor zum Höhlenkloster Tatev mit der weltweit längsten reversiblen Seilbahn „Wings of Tatev“.",
      hu: "Goris mintegy 1385 méter magasan, a Goris-folyó völgyében fekszik a déli Szjunik tartományban, Jerevántól körülbelül 240 kilométerre délkeletre, és nagyjából 20 ezer lakosával Örményország egyik legszebb kisvárosa. A mai települést 1870-ben alakították ki, egy német építész szabályos derékszögű terve alapján; emblematikus elemei a darabolt kőből emelt, kétemeletes polgárházak fafaragott erkélyekkel, a szőlővel és eperfával beültetett kis belső udvarok, és a széles Mastoc sugárút. Goris azonban elsősorban szürreális tufakőpiramisairól („kőerdőiről”) és a közeli Hndzoreszk falu ősi barlanglakásairól híres, melyeket részben még a 20. században is laktak, és amelyeket ma egy 160 méter hosszú modern függőhíd köt össze. Goris az utolsó örmény megállóhely a Hegyi-Karabahba (Sztepanakertbe) vezető stratégiai úton, az eperfapálinka (eperfavodka) központja, és kiindulópontja a Tatev sziklakolostornak, ahol a világ leghosszabb reverzibilis libegője, a „Wings of Tatev” közlekedik.",
      ro: "Goris se află la circa 1.385 de metri altitudine, într-o vale a râului Goris din provincia Siunik, la aproximativ 240 km sud-est de Erevan, și este, cu aproximativ 20.000 de locuitori, unul dintre cele mai frumoase orașe mici din Armenia. Localitatea actuală a fost reproiectată în 1870 după un plan ortogonal clar, întocmit de un arhitect german; sunt caracteristice casele burgheze cu două etaje din piatră brută, balcoanele din lemn sculptat, micile curți interioare cu viță-de-vie și duzi și largul bulevard Mashtots. Mai presus de toate, Goris este faimos pentru piramidele suprarealiste de tuf („pădurile de piatră”) din împrejurimi și pentru locuințele rupestre ale satului apropiat Khndzoresk, locuite în parte până în secolul XX și legate astăzi printr-un pod suspendat modern, lung de 160 m. Goris este ultima oprire armeană pe drumul strategic spre Karabahul de Munte (Stepanakert), centru al producției de țuică de dud și poarta spre mănăstirea rupestră Tatev, deservită de cea mai lungă telecabină reversibilă din lume, „Wings of Tatev”.",
      en: "Goris sits at about 1,385 metres altitude in a valley of the Goris River in the southern Syunik Province, some 240 km south-east of Yerevan, and with around 20,000 inhabitants is one of Armenia's most picturesque small towns. The present town was laid out in 1870 on a strict orthogonal plan by a German architect; its hallmarks are two-storey townhouses of rough stone with carved wooden balconies, small inner courtyards full of vines and mulberry trees and the broad Mashtots Avenue. Above all, Goris is famous for the surreal tuff pyramids – the so-called 'stone forests' – that surround it, and for the ancient cave dwellings of nearby Khndzoresk, partly inhabited well into the 20th century and now linked by a modern 160-metre suspension bridge. Goris is the last Armenian stop on the strategic road towards Nagorno-Karabakh (Stepanakert), a centre of mulberry-vodka production, and the gateway to the cliff-side Tatev monastery served by 'Wings of Tatev', the world's longest reversible cableway.",
      es: "Goris se encuentra a 1.385 metros de altitud en la provincia de Syunik, a 240 km de Ereván, y es considerada una de las ciudades más bellas de Armenia. Fue trazada en 1870 según un plano ortogonal de un arquitecto alemán; se caracteriza por sus casas de piedra de dos plantas con balcones de madera. Goris es famosa por sus pirámides de toba y las antiguas cuevas de Khndzoresk. Es la puerta de entrada al monasterio de Tatev, accesible mediante el teleférico más largo del mundo, y conocida por su aguardiente de moras.",
      pt: "Goris situa-se a 1.385 metros de altitude na província de Syunik, a 240 km de Erevan, sendo considerada uma das cidades mais bonitas da Arménia. Foi projetada em 1870 por um arquiteto alemão com um plano ortogonal; as suas casas de pedra de dois andares com varandas de madeira são icónicas. Goris é famosa pelas suas pirâmides de tufo (\"florestas de pedra\") e pelas habitações em cavernas de Khndzoresk. É a porta de entrada para o mosteiro de Tatev e famosa pela sua aguardente de amora.",
      fr: "Goris se trouve à 1 385 mètres d'altitude dans la province de Syunik, à 240 km d'Erevan, et est considérée comme l'une des plus belles villes d'Arménie. Elle a été aménagée en 1870 selon un plan en damier par un architecte allemand ; ses maisons en pierre à deux étages avec balcons en bois sont caractéristiques. Goris est célèbre pour ses pyramides de tuf et les anciennes grottes de Khndzoresk. C'est la porte d'entrée du monastère de Tatev, accessible par le plus long téléphérique du monde, et elle est réputée pour son eau-de-vie de mûre.",
    },
