    coords: [44.6469, 40.4078],
    name: { de: "Tscharenzawan", hu: "Csarencavan", ro: "Ciarențavan", en: "Charentsavan"},
    image: "/poi-images/armenia-charentsavan-cities-v2.webp",
    description: {
      de: "Tscharenzawan wurde Mitte des 20. Jahrhunderts als industrielles Zentrum für Maschinen- und Werkzeugbau gegründet.",
      hu: "Csarencavan a 20. század közepén jött létre, mint gépipari és szerszámgyártási központ.",
      ro: "Ciarențavan a fost înființat la mijlocul secolului al XX-lea ca un centru industrial pentru producția de mașini și unelte.",
      en: "Charentsavan was established in the mid-20th century as an industrial hub for machinery and tool manufacturing.",
      es: "Charentsavan fue fundada a mediados del siglo XX como un centro industrial para la ingeniería mecánica y de herramientas.",
      pt: "Charentsavan foi fundada em meados do século XX como um centro industrial para a construção de máquinas e ferramentas.",
      fr: "Tcharentsavan a été fondée au milieu du XXe siècle en tant que centre industriel pour la construction de machines et d'outils.",
    },
    descriptionAdvanced: {
      de: "Tscharenzawan entstand 1947 in der Provinz Kotajk auf rund 1.660 Metern Höhe als sozialistische Industriesiedlung am Hrasdan-Fluss, ursprünglich Lusawan („Lichtstadt“) genannt. Sie wuchs um ein Wasserkraftwerk in der Hrasdan-Kaskade und mehrere Maschinenbau- und Werkzeugwerke; in den 1970er Jahren wurde sie zu Ehren des großen armenischen Dichters Jeghische Tscharenz (1897–1937) in Tscharenzawan umbenannt. Mit aktuell rund 21.000 Einwohnern ist Tscharenzawan eine kompakte Stadt mit typisch sowjetischen Mikrorajons aus Tuffstein-Wohnblocks, einer Pionierhalle, einem Kulturpalast und einem markanten Tscharenz-Denkmal. Nach 1991 wurden die Großbetriebe stark zurückgefahren, doch in den letzten Jahren erlebt die Stadt eine Renaissance dank Lebensmittel- und Pharmaindustrie, IT-Subzentren und der Nähe zum Tsachkadsor-Skigebiet (12 km), zum Kloster Kecharis und zum Hrasdan-Stausee.",
      hu: "Csarencavan 1947-ben jött létre a Kotajk tartományban, mintegy 1660 méter magasan, a Hrazdan folyó mentén szocialista iparvárosként, eredetileg Lusavan („Fényváros”) néven. A település a Hrazdan-vízlépcső egyik vízerőműve és több gépipari, szerszámipari üzem köré épült; az 1970-es években, a nagy örmény költő, Jeghise Csarenc (1897–1937) tiszteletére kapta a Csarencavan nevet. Jelenlegi mintegy 21 ezer fős lakossága egy tipikus szovjet mikrorajonokkal teli, tufakő panelházakból álló kompakt városban él, ahol pionírház, kultúrpalota és egy karakteres Csarenc-emlékmű található. 1991 után a nagyüzemek nagy részét leépítették, de az elmúlt években az élelmiszer- és gyógyszeripar, az informatikai alközpontok, valamint a közeli Cahkadzori síközpont (12 km-re), a Kecharisz kolostor és a Hrazdan-víztározó miatt a város új lendületet kapott.",
      ro: "Ciarențavan a luat naștere în 1947 în provincia Kotaik, la circa 1.660 m altitudine, ca așezare industrială socialistă pe malul râului Hrazdan, sub numele inițial de Lusavan („Orașul Luminii”). A crescut în jurul unei hidrocentrale din cascada Hrazdan și al mai multor uzine de mașini și unelte; în anii 1970 a fost rebotezat Ciarențavan, în onoarea marelui poet armean Eghișe Ciarenț (1897–1937). În prezent, orașul are aproximativ 21.000 de locuitori și păstrează imaginea tipică a unei urbe sovietice, cu microcartiere de blocuri din tuf, casa pionierilor, palatul culturii și un monument expresiv dedicat lui Ciarenț. După 1991, marile uzine s-au restrâns puternic, dar în ultimii ani orașul cunoaște o renaștere datorită industriei alimentare și farmaceutice, subcentrelor IT și apropierii de stațiunea de schi Țakhkadzor (la 12 km), de mănăstirea Kecharis și de lacul de acumulare Hrazdan.",
      en: "Charentsavan was founded in 1947 in Kotayk Province at around 1,660 metres altitude as a socialist industrial town on the Hrazdan River, originally called Lusavan ('City of Light'). It grew up around a hydroelectric station of the Hrazdan cascade and several machinery and tool plants; in the 1970s it was renamed Charentsavan in honour of the great Armenian poet Yeghishe Charents (1897–1937). With its current 21,000 inhabitants Charentsavan remains a compact, classic Soviet town of tuff-clad apartment blocks arranged in microdistricts, with a Palace of Pioneers, a House of Culture and a striking Charents memorial. After 1991 most of its large factories were drastically scaled down, but in recent years the town has bounced back thanks to food and pharmaceutical industries, small IT hubs and its proximity to the Tsakhkadzor ski resort (12 km away), Kecharis monastery and the Hrazdan reservoir.",
      es: "Charentsavan surgió en 1947 en la provincia de Kotayk, a 1.660 metros de altitud, como un asentamiento industrial a orillas del río Hrazdan, originalmente llamado Lusavan. En la década de 1970 fue rebautizada en honor al gran poeta armenio Yeghishe Charents. Con unos 21.000 habitantes, es una ciudad compacta de bloques de toba de estilo soviético. Tras el declive industrial post-soviético, la ciudad vive hoy un renacimiento gracias a las industrias alimentaria y farmacéutica, así como a su proximidad a la estación de esquí de Tsaghkadzor.",
      pt: "Charentsavan surgiu em 1947 na província de Kotayk, a 1.660 metros de altitude, como um assentamento industrial junto ao rio Hrazdan, originalmente chamado Lusavan. Na década de 1970 foi renomeada em honra do poeta Yeghishe Charents. Com cerca de 21.000 habitantes, é uma cidade compacta composta por blocos de apartamentos de tufo típicos da era soviética. Após 1991, a indústria pesada diminuiu, mas a cidade recuperou graças ao setor alimentar e farmacêutico e à proximidade da estância de esqui de Tsaghkadzor.",
      fr: "Tcharentsavan a été créée en 1947 dans la province de Kotayk, à 1 660 mètres d'altitude, en tant que colonie industrielle sur la rivière Hrazdan, initialement nommée Lousavan. Dans les années 1970, elle a été renommée en l'honneur du poète Yeghishe Tcharents. Avec environ 21 000 habitants, c'est une ville compacte de blocs d'appartements en tuf typiquement soviétiques. Aujourd'hui, elle connaît une renaissance grâce aux industries alimentaire et pharmaceutique et à sa proximité avec la station de ski de Tsaghkadzor.",
    },
