    image: "/poi-images/armenia-ararat-cities-v2.webp",
    description: {
      de: "Die Stadt Ararat ist eine Industriestadt in der Ararat-Ebene, die vor allem für ihre große Zementfabrik bekannt ist.",
      hu: "Ararát egy iparváros az Ararát-síkságon, amely elsősorban hatalmas cementgyáráról ismert.",
      ro: "Orașul Ararat este un oraș industrial din câmpia Ararat, cunoscut în principal pentru marea sa fabrică de ciment.",
      en: "The city of Ararat is an industrial town in the Ararat plain, known primarily for its large cement factory.",
      es: "La ciudad de Ararat es una ciudad industrial en la llanura de Ararat, conocida sobre todo por su gran fábrica de cemento.",
      pt: "A cidade de Ararat é uma cidade industrial na planície de Ararat, conhecida principalmente pela sua grande fábrica de cimento.",
      fr: "La ville d'Ararat est une cité industrielle de la plaine de l'Ararat, principalement connue pour sa grande cimenterie.",
    },
    descriptionAdvanced: {
      de: "Die Stadt Ararat liegt rund 50 Kilometer südlich von Eriwan in der Ararat-Ebene auf etwa 825 Metern Höhe und teilt ihren Namen mit dem berühmten Doppelvulkan jenseits der türkischen Grenze. Sie wurde 1939 als Industriesiedlung um die große Zementfabrik gegründet und erhielt 1947 Stadtrecht; seit den 1960er Jahren kam ein bedeutendes Goldlaugungswerk hinzu, das Erze aus den Bergen von Sotk und Ararat verarbeitete. In Sowjetzeiten lebte ein Großteil der etwa 22.000 Einwohner direkt oder indirekt von der Zementproduktion und der Goldindustrie; nach 1991 wurden beide Werke zeitweise geschlossen, modernisiert und teilweise an internationale Konzerne (Lafarge, GeoProMining) verkauft. Heute ist Ararat ein typisches südarmenisches Industriestädtchen mit sowjetischer Plattenbauarchitektur, lebendigem Bazar, einer schönen Aussicht auf den Berg Ararat im Süden, dem Naturschutzgebiet Khosrov-Wald im Osten und dem nahen Höhlenkloster Khor Virap im Westen.",
      hu: "Ararát város Jerevántól mintegy 50 kilométerre délre, az Ararát-síkságon, körülbelül 825 méter magasan fekszik, és nevét a török határ túloldalán emelkedő, kettős csúcsú vulkánnal osztja. 1939-ben hozták létre iparvárosként a hatalmas cementgyár köré, és 1947-ben kapott városi rangot; az 1960-as évektől jelentős aranykinyerő üzemmel is bővült, amely a szotki és ararati hegyekből származó érceket dolgozta fel. A szovjet korszakban a mintegy 22 ezer lakos nagy része közvetlenül vagy közvetve a cement- és aranyiparból élt; 1991 után mindkét üzemet ideiglenesen leállították, korszerűsítették, részben nemzetközi konszerneknek (Lafarge, GeoProMining) értékesítették. Ararát ma egy tipikus dél-örmény iparváros, szovjet panelházakkal, élénk bazárral, az Ararát-hegyre nyíló pompás kilátással délre, a Hoszrov-erdő természetvédelmi területtel keletre és a közeli Hor Virap sziklakolostorral nyugatra.",
      ro: "Orașul Ararat este situat la aproximativ 50 km sud de Erevan, în câmpia Ararat, la circa 825 de metri altitudine, și împarte numele cu vulcanul dublu de dincolo de granița turcă. A fost înființat în 1939 ca așezare industrială în jurul marii fabrici de ciment și a primit statutul de oraș în 1947; din anii 1960 i s-a adăugat și o importantă uzină de extragere a aurului, care prelucra minereuri din munții Sotk și Ararat. În epoca sovietică, mare parte din cei aproximativ 22.000 de locuitori trăiau direct sau indirect din industria cimentului și a aurului; după 1991, ambele uzine au fost închise temporar, modernizate și parțial vândute unor mari concerne internaționale (Lafarge, GeoProMining). Astăzi Ararat este un oraș industrial tipic din sudul Armeniei, cu blocuri sovietice, bazar viu, o priveliște superbă spre Muntele Ararat la sud, rezervația naturală Khosrov la est și mănăstirea rupestră Khor Virap la vest.",
      en: "The town of Ararat lies about 50 km south of Yerevan on the Ararat plain at roughly 825 metres altitude, sharing its name with the famous twin-peaked volcano just across the Turkish border. It was founded in 1939 as an industrial settlement around a large cement works and received town status in 1947; from the 1960s a major gold-extraction plant was added, processing ore from the mountains of Sotk and Ararat. In Soviet times most of its 22,000-odd inhabitants depended directly or indirectly on the cement and gold industries; after 1991 both plants were temporarily closed, modernised and partially sold to international groups such as Lafarge and GeoProMining. Today Ararat is a typical southern Armenian industrial town of Soviet-era apartment blocks, with a lively bazaar, splendid views of Mount Ararat to the south, the Khosrov forest reserve to the east and the cliff-top Khor Virap monastery just to the west.",
      es: "La ciudad de Ararat se encuentra a unos 50 kilómetros al sur de Ereván en la llanura de Ararat, a 825 metros de altura, y comparte su nombre con el famoso volcán doble al otro lado de la frontera turca. Fue fundada en 1939 como asentamiento industrial alrededor de la gran fábrica de cemento. Desde los años 60, se añadió una importante planta de extracción de oro que procesaba minerales de las montañas de Sotk. Tras 1991, ambas fábricas fueron modernizadas y parcialmente vendidas a corporaciones internacionales. Hoy, Ararat es una típica ciudad industrial del sur de Armenia con arquitectura soviética, un bazar animado y hermosas vistas al Monte Ararat al sur y al cercano monasterio de Khor Virap al oeste.",
      pt: "A cidade de Ararat situa-se a cerca de 50 quilómetros a sul de Erevan, na planície de Ararat, a cerca de 825 metros de altitude, e partilha o nome com o famoso vulcão duplo do outro lado da fronteira turca. Foi fundada em 1939 como um assentamento industrial em redor da grande fábrica de cimento e recebeu o estatuto de cidade em 1947. Desde a década de 1960, foi adicionada uma importante central de extração de ouro, que processava minérios das montanhas de Sotk e Ararat. Hoje, Ararat é uma típica cidade industrial do sul da Arménia com arquitetura soviética de blocos, um bazar animado e uma bela vista para o Monte Ararat a sul e para o mosteiro de Khor Virap a oeste.",
      fr: "La ville d'Ararat se trouve à environ 50 kilomètres au sud d'Erevan, dans la plaine de l'Ararat, à environ 825 mètres d'altitude, et partage son nom avec le célèbre volcan situé de l'autre côté de la frontière turque. Elle a été fondée en 1939 en tant que cité industrielle autour de la grande cimenterie. À partir des années 1960, une importante usine d'extraction d'or a été ajoutée, traitant les minerais provenant des montagnes de Sotk et d'Ararat. Aujourd'hui, Ararat est une petite ville industrielle typique du sud de l'Arménie avec son architecture soviétique, son bazar animé, une belle vue sur le mont Ararat au sud et le monastère de Khor Virap à proximité vers l'ouest.",
    },
