    type: "city",
    parent: "AM-AR",
    coords: [44.4444, 40.0681],
    name: { de: "Masis", hu: "Maszisz", ro: "Masis", en: "Masis"},
    image: "/poi-images/armenia-masis-cities-v2.webp",
    description: {
      de: "Masis ist ein wichtiger Eisenbahnknotenpunkt und Industriezentrum in der landwirtschaftlichen Provinz Ararat.",
      hu: "Maszisz jelentős vasúti csomópont és ipari központ a mezőgazdasági Ararát tartományban.",
      ro: "Masis este un important nod feroviar și centru industrial situat în provincia agricolă Ararat.",
      en: "Masis is a notable railway junction and industrial center located in the agricultural Ararat Province.",
      es: "Masis es un importante nudo ferroviario y centro industrial en la provincia agrícola de Ararat.",
      pt: "Masis é um importante nó ferroviário e centro industrial na província agrícola de Ararat.",
      fr: "Masis est un carrefour ferroviaire et un centre industriel important dans la province agricole d'Ararat.",
    },
    descriptionAdvanced: {
      de: "Masis liegt rund 12 Kilometer südlich von Eriwan in der Provinz Ararat und trägt den traditionellen armenischen Namen für den Berg Ararat. Die Stadt entstand in den 1930er Jahren als Eisenbahnsiedlung an der wichtigen Strecke Eriwan–Nachitschewan, hieß bis 1969 Salinino und seither Masis. Mit etwa 20.000 Einwohnern ist sie heute Verwaltungszentrum eines bedeutenden landwirtschaftlichen Bezirks, der vor allem für seine Tomaten, Wassermelonen, Aprikosen und Trauben bekannt ist. Der Bahnhof Masis ist nach wie vor einer der wichtigsten Güterumschlagplätze des Landes, mit großen Rangierbahnhöfen und Lagerhäusern; daneben gibt es Lebensmittel-, Beton- und Verpackungsfabriken, Logistikzentren und ein Industriepark mit Bezug zu chinesischen Investoren. Die kompakte Stadt ist von endlosen bewässerten Feldern umgeben, im Hintergrund stehen die imposante Ararat-Doppelspitze und die vulkanischen Geghama-Berge, und sie ist Pendlerziel für viele Beschäftigte in Eriwan.",
      hu: "Maszisz Jerevántól mintegy 12 kilométerre délre, az Ararát tartományban fekszik, és az Ararát-hegy hagyományos örmény nevét viseli. A város a 20. század első felében jött létre vasutas településként a fontos Jereván–Nahicseván vonal mentén, és 1969-ig Zalinino, azóta Maszisz néven szerepel. Mintegy 20 ezer lakosával ma egy jelentős mezőgazdasági járás közigazgatási központja, amely elsősorban paradicsomáról, dinnyéiről, sárgabarackjáról és szőlőjéről híres. A maszisz vasútállomás máig az ország egyik legfontosabb áru-átrakó pontja, hatalmas rendezőpályaudvarokkal és raktárakkal; emellett élelmiszer-, beton- és csomagolóüzemek, logisztikai központok, valamint kínai befektetésekhez kötődő ipari park is működik itt. A kompakt várost végeláthatatlan öntözött szántóföldek veszik körül, háttérben az imozáns kettőscsúcsú Ararát és a vulkáni Geham-hegyek, és sok jereváni dolgozó ingázik ide.",
      ro: "Masis se află la circa 12 km sud de Erevan, în provincia Ararat, și poartă numele tradițional armean al Muntelui Ararat. Orașul a apărut la începutul secolului XX ca așezare feroviară pe importanta linie Erevan–Nahicevan, s-a numit Zalinino până în 1969, iar de atunci Masis. Cu aproximativ 20.000 de locuitori, este astăzi centrul administrativ al unui district agricol important, faimos mai ales pentru roșiile, pepenii, caisele și strugurii săi. Gara Masis este în continuare unul dintre cele mai importante puncte de transbordare a mărfurilor din țară, cu mari triaje și depozite; pe lângă aceasta, funcționează aici fabrici de alimente, de betoane și de ambalaje, centre logistice și un parc industrial legat de investitori chinezi. Orașul compact este înconjurat de câmpuri irigate fără sfârșit, pe fundal se înalță silueta dublă a Araratului și munții vulcanici Gegham, iar mulți locuitori navetează zilnic spre Erevan.",
      en: "Masis lies about 12 km south of Yerevan in Ararat Province and bears the traditional Armenian name for Mount Ararat. The town grew up in the early 20th century as a railway settlement on the important Yerevan–Nakhichevan line; it was called Zalinino until 1969 and Masis ever since. With around 20,000 inhabitants it now serves as the administrative centre of an important agricultural district famous especially for its tomatoes, watermelons, apricots and grapes. Masis station remains one of the country's main freight transhipment points, with extensive marshalling yards and warehouses; alongside it operate food-processing, concrete and packaging plants, logistics hubs and an industrial park linked to Chinese investors. The compact town is surrounded by endless irrigated fields, with the imposing twin peaks of Ararat and the volcanic Geghama mountains rising in the background, and it serves as a major commuter base for workers in Yerevan.",
      es: "Situada a 12 kilómetros al sur de Ereván, Masis lleva el nombre tradicional armenio del monte Ararat. Surgió en la década de 1930 como asentamiento ferroviario en la ruta estratégica Ereván-Najicheván. Con unos 20.000 habitantes, es el centro administrativo de una zona agrícola clave, famosa por sus tomates, albaricoques y uvas. Su estación de tren sigue siendo uno de los mayores centros de carga del país. La ciudad está rodeada de campos de regadío y ofrece vistas impresionantes de las dos cumbres del Ararat y de las montañas Geghama, siendo un destino residencial para muchos trabajadores de la capital.",
      pt: "Localizada a 12 quilómetros a sul de Erevan, Masis ostenta o nome tradicional arménio para o monte Ararat. Surgiu na década de 1930 como um povoado ferroviário na rota estratégica Erevan-Nakhchivan. Com cerca de 20.000 habitantes, é o centro administrativo de uma zona agrícola fundamental, famosa pelos seus tomates, damascos e uvas. A sua estação ferroviária continua a ser um dos maiores centros de carga do país. A cidade está rodeada por campos irrigados e oferece vistas impressionantes dos picos gémeos do Ararat e das montanhas Geghama, sendo um destino residencial para muitos trabalhadores da capital.",
      fr: "Située à 12 kilomètres au sud d'Erevan dans la province d'Ararat, Masis porte le nom traditionnel arménien du mont Ararat. La ville s'est développée dans les années 1930 comme cité cheminote sur la ligne Erevan-Nakhitchevan. Avec environ 20 000 habitants, elle est le centre administratif d'un district agricole majeur produisant tomates, abricots et raisins. La gare de Masis reste l'un des plus importants centres de fret du pays, avec de vastes zones de stockage et des zones industrielles attirant des investissements internationaux. La ville est entourée de champs irrigués, avec en toile de fond les sommets de l'Ararat et les montagnes de Geghama.",
    },
