      es: ["La ciudad se llamó Hrazdan hasta 1969.", "Masis se encuentra a una altitud de unos 830 metros.", "La estación de Masis es la mayor estación de clasificación de Armenia.", "Alberga una de las mayores fábricas de tabaco (International Masis Tabak).", "Ofrece una de las mejores vistas panorámicas del monte Ararat.", "Fundada en 1950 como asentamiento obrero."],
