    description: {
      de: "Aschtarak ist eine alte Stadt, die sich über die Schlucht des Flusses Kasagh erstreckt und reich an mittelalterlichen Brücken und alten Kirchen ist.",
      hu: "Astarak egy ősi város, amely a Kaszagh folyó szurdokán ível át, és gazdag középkori hidakban, valamint régi templomokban.",
      ro: "Aștarak este un oraș antic care se întinde pe defileul râului Kasagh, bogat în poduri medievale și biserici vechi.",
      en: "Ashtarak is an ancient city straddling the Kasagh River gorge, rich in medieval bridges and old churches.",
      es: "Ashtarak es una ciudad antigua que se extiende sobre el desfiladero del río Kasagh y es rica en puentes medievales e iglesias antiguas.",
      pt: "Ashtarak é uma cidade antiga que se estende sobre o desfiladeiro do rio Kasagh, sendo rica em pontes medievais e igrejas antigas.",
      fr: "Achtarak est une ville ancienne qui s'étend sur les gorges de la rivière Kasagh, riche en ponts médiévaux et en églises anciennes.",
    },
    descriptionAdvanced: {
      de: "Aschtarak liegt etwa 20 Kilometer nordwestlich von Eriwan in der Provinz Aragazotn auf rund 1.100 Metern Höhe und ist das historische und administrative Zentrum der Region am Fuße des erloschenen Vulkans Aragaz (4.090 m), des höchsten Berges Armeniens. Die Stadt mit knapp 20.000 Einwohnern erstreckt sich beidseits der tiefen Schlucht des Flusses Kasagh und ist berühmt für ihre dreibogige mittelalterliche Steinbrücke aus dem 17. Jahrhundert. Im historischen Kern stehen die kleine Kirche Karmrawor („die Rote“, 7. Jh.), eine der ältesten erhaltenen Kreuzkuppelkirchen Armeniens, dazu Marine, Sjurb Sargis und die Kirche Spitakawor. Aschtarak gilt als Geburtsort vieler bedeutender armenischer Schriftsteller, wie Perdsch Proschjan und Nar-Dos, und ist von Aprikosenhainen umgeben; die Region erlebt heute einen wirtschaftlichen Aufschwung dank Tomatenpaste, Wein und Tourismus mit Ausflügen zum Kloster Saghmosawank, Hovhannawank und zum Pantheon Hayazor.",
      hu: "Astarak Jerevántól mintegy 20 kilométerre északnyugatra, az Aragacotn tartományban fekszik, körülbelül 1100 méter magasan, és a régió történelmi és közigazgatási központja a kialudt Aragac-vulkán (4090 m), Örményország legmagasabb csúcsa lábánál. A közel 20 ezer lakosú város a Kaszagh folyó mély szurdokának mindkét oldalán terül el, és híres a 17. századi háromboltíves középkori kőhídjáról. Történelmi magjában áll a kis Karmravor templom („A vörös”, 7. század), Örményország egyik legrégebben fennmaradt keresztkupolás temploma, valamint a Marine-, a Szurb Szárgisz- és a Spitakavor-templom. Astarak több jelentős örmény író szülőhelye, így Percs Prosjan és Nar-Doszé, és sárgabarack-ültetvények veszik körül; ma a régió gazdasági fellendülést él át a paradicsompüré, a borászat és a Saghmoszavank, Hovhannavank kolostorokhoz, valamint a Hajazor Panteonhoz vezető turizmus révén.",
      ro: "Aștarak se află la circa 20 km nord-vest de Erevan, în provincia Aragațotn, la aproximativ 1.100 m altitudine, și este centrul istoric și administrativ al regiunii, la poalele vulcanului stins Aragaț (4.090 m), cel mai înalt munte al Armeniei. Orașul, cu aproape 20.000 de locuitori, se întinde pe ambele maluri ale defileului adânc al râului Kasagh și este faimos pentru podul medieval din piatră cu trei arcade, din secolul al XVII-lea. În centrul istoric se află mica biserică Karmravor („Cea Roșie”, sec. VII), una dintre cele mai vechi biserici armene cu cupolă pe cruce păstrate, alături de bisericile Marine, Surp Sargis și Spitakavor. Aștarak este orașul natal al mai multor scriitori armeni importanți, precum Perci Proșian și Nar-Dos, și este înconjurat de livezi de caiși; astăzi regiunea cunoaște un avânt economic datorită pastei de tomate, vinificației și turismului spre mănăstirile Saghmosavank, Hovhannavank și panteonul Hayazor.",
      en: "Ashtarak lies about 20 km north-west of Yerevan in Aragatsotn Province at roughly 1,100 metres altitude and is the historic and administrative centre of the region at the foot of the extinct Aragats volcano (4,090 m), Armenia's highest mountain. The town, home to just under 20,000 people, spreads along both sides of the deep gorge of the Kasagh River and is famous for its three-arched medieval stone bridge of the 17th century. In its historic core stands the tiny Karmravor church ('the red one', 7th century), one of Armenia's oldest surviving cross-domed churches, together with the Marine, Surp Sargis and Spitakavor churches. Ashtarak is the birthplace of several major Armenian writers, including Perch Proshyan and Nar-Dos, and is surrounded by apricot orchards; the region is now experiencing an economic revival thanks to tomato paste, winemaking and tourism centred on the monasteries of Saghmosavank and Hovhannavank and the Hayazor pantheon.",
      es: "Ashtarak se encuentra a unos 20 km de Ereván, en la provincia de Aragatsotn, a unos 1.100 metros de altitud al pie del volcán extinto Aragats. Con casi 20.000 habitantes, la ciudad se extiende a ambos lados del profundo desfiladero del río Kasagh y es famosa por su puente de piedra del siglo XVII. En su núcleo histórico destacan la iglesia de Karmravor del siglo VII, una de las iglesias con cúpula cruzada mejor conservadas de Armenia, así como las iglesias de Marine y Spitakavor. Rodeada de huertos de albaricoques, Ashtarak es también el lugar de nacimiento de destacados escritores armenios y un centro para el turismo regional.",
      pt: "Ashtarak situa-se a cerca de 20 km de Erevan, na província de Aragatsotn, a 1.100 metros de altitude, no sopé do vulcão extinto Aragats. Com quase 20.000 habitantes, a cidade estende-se por ambos os lados do profundo desfiladeiro do rio Kasagh e é famosa pela sua ponte de pedra do século XVII. No centro histórico encontram-se a igreja de Karmravor (século VII), Marine e Spitakavor. Rodeada de pomares de damascos, a região é berço de escritores arménios famosos e vive um crescimento económico graças à produção de vinho e ao turismo.",
      fr: "Achtarak se situe à 20 km d'Erevan, dans la province d'Aragatsotn, à 1 100 mètres d'altitude au pied du volcan éteint Aragats. Avec près de 20 000 habitants, la ville s'étend de part et d'autre des gorges de la rivière Kasagh et est célèbre pour son pont médiéval du XVIIe siècle. Le centre historique abrite l'église Karmravor du VIIe siècle, l'une des plus anciennes églises à coupole croisée d'Arménie, ainsi que les églises Marine et Spitakavor. Entourée de vergers d'abricotiers, Achtarak est le lieu de naissance de grands écrivains arméniens et connaît un essor touristique et économique.",
    },
