      pt: ["Capital da província de Aragatsotn.", "Situada nas margens do rio Kasagh.", "Alberga a igreja de Karmravor do século VII.", "A população é de cerca de 18.000 habitantes.", "Localiza-se a uma altitude de 1.110 metros acima do nível do mar.", "Mencionada pela primeira vez em documentos no século IX."],
      fr: ["Capitale de la province d'Aragatsotn.", "Située sur les rives de la rivière Kasagh.", "Abrite l'église Karmravor du VIIe siècle.", "La population est d'environ 18 000 habitants.", "Se trouve à une altitude de 1 110 mètres au-dessus du niveau de la mer.", "Mentionnée pour la première fois dans des documents du IXe siècle."],
