    type: "city",
    parent: "AM-GR",
    coords: [44.9542, 40.5511],
    name: { de: "Sewan", hu: "Szeván", ro: "Sevan", en: "Sevan"},
    image: "/poi-images/armenia-sevan-cities-v2.webp",
    description: {
      de: "Sewan ist ein beliebter Urlaubsort an den Ufern des Sewansees, dem größten Gewässer Armeniens.",
      hu: "Szeván egy népszerű üdülőváros a Szeván-tó, Örményország legnagyobb vízfelületének partján.",
      ro: "Sevan este o stațiune populară pe malul Lacului Sevan, cel mai mare corp de apă din Armenia.",
      en: "Sevan is a popular resort town on the shores of Lake Sevan, Armenia's largest body of water.",
      es: "Sevan es un popular centro vacacional a orillas del lago Sevan, la mayor masa de agua de Armenia.",
      pt: "Sevan é um popular centro de férias nas margens do lago Sevan, a maior massa de água da Arménia.",
      fr: "Sevan est une station balnéaire populaire sur les rives du lac Sevan, la plus grande étendue d'eau d'Arménie.",
    },
    descriptionAdvanced: {
      de: "Sewan liegt am Nordwestufer des gleichnamigen Sees auf rund 1.925 Metern Höhe in der Provinz Gegharkunik, etwa 60 Kilometer nordöstlich von Eriwan, und ist mit etwa 19.000 Einwohnern wichtigste Tourismus- und Erholungsstadt Armeniens. Der Sewansee selbst ist mit 1.240 km² einer der größten Hochgebirgsseen der Welt und gilt als „blaues Auge“ Armeniens; an seinen Ufern produziert die Region Forelle, Krebse, Honig und Gergerschmuck. Direkt bei der Stadt erhebt sich auf einer ehemaligen Insel, die durch Absenkung des Sees in der Sowjetzeit zur Halbinsel wurde, das Kloster Sewanawank aus dem 9. Jahrhundert mit zwei Kuppelkirchen und einem berühmten Khatschkar. Sewan war in der Sowjetzeit ein zentrales Industrie- und Eisenbahnknotenzentrum mit elektromechanischer Industrie; heute leben die Bewohner überwiegend von Tourismus, Restaurants, Strandhotels, Wassersport und der Verarbeitung von Sewan-Forellen sowie von der riesigen Bahnstation an der Linie Eriwan–Tiflis.",
      hu: "Szeván a Szeván-tó északnyugati partján, mintegy 1925 méter magasan, a Geharkunik tartományban fekszik, Jerevántól körülbelül 60 kilométerre északkeletre, és nagyjából 19 ezer lakosával Örményország legfontosabb turisztikai és üdülővárosa. Maga a Szeván-tó 1240 km²-es felületével a világ egyik legnagyobb hegyvidéki tava, és Örményország „kék szemeként” emlegetik; partjain pisztránggal, rákokkal, mézzel, kézművesékszerekkel foglalkoznak. A városhoz közvetlenül egy hajdani sziget kapcsolódik, amely a szovjet korszakbeli vízszintsüllyesztés miatt félszigetté vált; itt áll a 9. századi Szevanavank kolostor két kupolás templommal és híres hacskárral. Szeván a szovjet időkben fontos ipari és vasúti csomópont volt elektromechanikai gyárakkal; ma lakói döntő részben a turizmusból, éttermekből, partmenti szállodákból, vízisportokból, a szevánai pisztráng feldolgozásából, valamint a Jereván–Tbiliszi vasútvonalon működő nagyméretű vasútállomásból élnek.",
      ro: "Sevan se află pe malul nord-vestic al lacului cu același nume, la circa 1.925 m altitudine, în provincia Gegharkunik, la aproximativ 60 km nord-est de Erevan, și, cu aproximativ 19.000 de locuitori, este cel mai important oraș turistic și balnear din Armenia. Lacul Sevan, cu o suprafață de 1.240 km², este unul dintre cele mai mari lacuri montane din lume și este supranumit „ochiul albastru” al Armeniei; pe malurile sale se cresc păstrăvi, raci, se produce miere și bijuterii artizanale. Lângă oraș, pe o fostă insulă devenită peninsulă în urma scăderii nivelului apei în perioada sovietică, se înalță mănăstirea Sevanavank din secolul al IX-lea, cu două biserici cu cupolă și o cruce de piatră (khachkar) celebră. În epoca sovietică, Sevan a fost un nod industrial și feroviar important, cu uzine electromecanice; astăzi locuitorii trăiesc majoritar din turism, restaurante, hoteluri pe plajă, sporturi nautice, prelucrarea păstrăvului de Sevan și din marea gară aflată pe linia Erevan–Tbilisi.",
      en: "Sevan stands on the north-western shore of the lake of the same name at roughly 1,925 metres altitude in Gegharkunik Province, about 60 km north-east of Yerevan, and with around 19,000 inhabitants is Armenia's most important tourist and resort town. Lake Sevan itself, covering 1,240 km², is one of the largest high-altitude lakes in the world and is known as Armenia's 'blue eye'; its shores are devoted to trout and crayfish farming, honey and folk jewellery. Right by the town, on a former island that became a peninsula after Soviet-era water-level lowering, rises the 9th-century Sevanavank monastery with its two domed churches and famous khachkar (cross-stone). In Soviet times Sevan was a major industrial and railway hub with electromechanical plants; today its inhabitants live mostly from tourism, restaurants, beach hotels, watersports, processing of Sevan trout and from the huge railway station on the Yerevan–Tbilisi line.",
      es: "Situada a 1.925 metros de altitud en la provincia de Gegharkunik, Sevan es la ciudad turística más importante de Armenia. El lago Sevan, conocido como el 'ojo azul' del país, es uno de los lagos alpinos más grandes del mundo. En una antigua isla (ahora península) se alza el monasterio de Sevanavank, fundado en el siglo IX, con sus emblemáticas iglesias y khachkars. Aunque fue un centro industrial en la época soviética, hoy la ciudad vive del turismo, los deportes acuáticos, la gastronomía y la pesca de truchas, además de ser una estación clave en la línea ferroviaria Ereván-Tiflis.",
      pt: "Situada a 1.925 metros de altitude na província de Gegharkunik, Sevan é a cidade turística mais importante da Arménia. O lago Sevan, conhecido como o 'olho azul' do país, é um dos maiores lagos alpinos do mundo. Numa antiga ilha (agora península) ergue-se o mosteiro de Sevanavank, fundado no século IX, com as suas igrejas emblemáticas. Embora tenha sido um centro industrial na era soviética, hoje a cidade vive do turismo, desportos náuticos, gastronomia e pesca de truta, além de ser uma estação fundamental na linha ferroviária Erevan-Tbilissi.",
      fr: "Sevan, située à 1 925 mètres d'altitude dans la province de Gegharkunik, est la principale ville touristique d'Arménie. Le lac Sevan lui-même, surnommé « l'œil bleu » de l'Arménie, est l'un des plus grands lacs de haute montagne au monde. À proximité immédiate de la ville, sur une ancienne île devenue péninsule, se dresse le monastère de Sevanavank datant du IXe siècle, avec ses églises à coupole et ses célèbres khachkars. Autrefois centre industriel, la ville vit aujourd'hui principalement du tourisme, des hôtels de plage, des sports nautiques et de la transformation de la truite de Sevan.",
    },
