    coords: [43.9725, 40.6158],
    name: { de: "Artik", hu: "Artik", ro: "Artik", en: "Artik"},
    image: "/poi-images/armenia-artik-cities-v2.webp",
    description: {
      de: "Artik ist weithin bekannt für seine ausgedehnten Tuffsteinbrüche, die Baumaterialien für das ganze Land geliefert haben.",
      hu: "Artik széles körben ismert kiterjedt tufabányáiról, amelyek az egész ország számára biztosítottak építőanyagot.",
      ro: "Artik este recunoscut pe scară largă pentru carierele sale extinse de piatră de tuf, care au furnizat materiale de construcție în toată țara.",
      en: "Artik is widely known for its extensive tuff stone quarries, which have supplied building materials across the country.",
      es: "Artik es ampliamente conocida por sus extensas canteras de toba, que han suministrado materiales de construcción para todo el país.",
      pt: "Artik é amplamente conhecida pelas suas extensas pedreiras de tufo, que forneceram materiais de construção para todo o país.",
      fr: "Artik est largement connue pour ses vastes carrières de tuf, qui ont fourni des matériaux de construction pour tout le pays.",
    },
    descriptionAdvanced: {
      de: "Artik liegt in der nordwestlichen Provinz Schirak, etwa 30 Kilometer südöstlich von Gjumri und 90 Kilometer nördlich von Eriwan, auf rund 1.700 Metern Höhe an den südlichen Ausläufern des Aragaz-Bergmassivs. Die Stadt mit etwa 14.000 Einwohnern wurde 1945 zur Stadt erhoben und ist seit dem 19. Jahrhundert berühmt für ihre riesigen, terrassenartig in den Vulkanhang geschnittenen Tagebaue, in denen rosa-, beige- und cremefarbener Tuffstein gewonnen wird. Dieser Stein hat zahlreiche Bauwerke in ganz Armenien geprägt, darunter weite Teile von Eriwan und das Mausoleum Lenins in Moskau. Artik wurde durch das Erdbeben von 1988 schwer beschädigt; viele Wohnblöcke aus den 1970er Jahren stürzten ein. Heute ist die Stadt ein Zentrum der Tuff- und Basaltverarbeitung, mit Steinmetz- und Skulpturwerkstätten, einer schönen mittelalterlichen Kirche St. Geworg und der nahegelegenen Kreuzkuppelkirche Lmbatawank aus dem 7. Jahrhundert.",
      hu: "Artik az északnyugati Sirak tartományban fekszik, Gjümritől mintegy 30 kilométerre délkeletre, Jerevántól pedig 90 kilométerre északra, körülbelül 1700 méter magasan, az Aragac-hegy déli lejtőjén. A mintegy 14 ezer lakosú város 1945-ben kapott városi rangot, és a 19. század óta híres a vulkáni hegyoldalba teraszosan vágott hatalmas külszíni bányáiról, ahol rózsaszín, bézs és krémszínű tufakövet termelnek ki. Ez a kőzet számos örményországi épület alapanyagát adja, köztük Jereván nagy részéét és a moszkvai Lenin-mauzóleumét is. Artikot az 1988-as földrengés súlyosan megrongálta; az 1970-es években emelt panelházak közül sok összeomlott. Ma a város a tufa- és bazaltfeldolgozás központja, kőfaragó- és szobrászműhelyekkel, gyönyörű középkori Szent Gevorg templommal és a közeli, 7. századi Lmbatavank kereszt-kupolás templommal.",
      ro: "Artik se află în provincia nord-vestică Șirak, la circa 30 km sud-est de Gyumri și 90 km nord de Erevan, la aproximativ 1.700 m altitudine, pe versanții sudici ai masivului Aragaț. Orașul, cu aproximativ 14.000 de locuitori, a primit statutul de oraș în 1945 și este faimos încă din secolul al XIX-lea pentru carierele sale uriașe, tăiate în terase pe versantul vulcanic, unde se extrage piatră de tuf în nuanțe roz, bej și crem. Această piatră a marcat numeroase clădiri din întreaga Armenie, inclusiv mare parte din Erevan și Mausoleul lui Lenin din Moscova. Artik a fost grav avariat de cutremurul din 1988; multe blocuri de locuințe din anii 1970 s-au prăbușit. Astăzi orașul este un centru al prelucrării tufului și bazaltului, cu ateliere de pietrari și sculptori, o frumoasă biserică medievală Sf. Gheorghe și, în apropiere, biserica Lmbatavank din secolul al VII-lea.",
      en: "Artik lies in the north-western Shirak Province, about 30 km south-east of Gyumri and 90 km north of Yerevan, at roughly 1,700 metres altitude on the southern slopes of the Aragats massif. The town, home to around 14,000 inhabitants, was granted city status in 1945 and has been famous since the 19th century for its huge open-pit quarries, terraced into the volcanic slope, which yield pink, beige and cream-coloured tuff. This stone has shaped countless buildings across Armenia, including much of Yerevan and Lenin's mausoleum in Moscow. Artik was severely damaged by the 1988 earthquake; many of the 1970s apartment blocks collapsed. The city is today a centre of tuff and basalt processing, with stone-cutting and sculpting workshops, a beautiful medieval Surb Gevorg church and, nearby, the 7th-century cross-domed Lmbatavank church.",
      es: "Artik está situada en la provincia de Shirak, a unos 30 kilómetros de Guiumri y 90 kilómetros de Ereván, a 1.700 metros de altitud. Con unos 14.000 habitantes, la ciudad es famosa desde el siglo XIX por sus enormes canteras de toba de color rosa, beige y crema. Esta piedra se utilizó en numerosos edificios de Armenia, incluido gran parte de Ereván y el mausoleo de Lenin en Moscú. Dañada por el terremoto de 1988, hoy Artik es un centro de procesamiento de toba y basalto, con talleres de escultura y monumentos como la iglesia de San Jorge y la iglesia de Lmbatavank del siglo VII.",
      pt: "Artik situa-se na província de Shirak, a 30 km de Gyumri e 90 km de Erevan, a cerca de 1.700 metros de altitude. Com cerca de 14.000 habitantes, a cidade é famosa desde o século XIX pelas suas enormes pedreiras de tufo rosa, bege e creme. Esta pedra moldou numerosos edifícios em toda a Arménia, incluindo grande parte de Erevan e o mausoléu de Lenine em Moscovo. Artik foi gravemente danificada pelo terramoto de 1988, mas hoje é um centro de processamento de tufo e basalto, albergando a igreja de São Jorge e a igreja de Lmbatavank, do século VII.",
      fr: "Artik est située dans la province de Shirak, à 30 km de Gyumri et 90 km d'Erevan, à environ 1 700 mètres d'altitude. La ville de 14 000 habitants est célèbre depuis le XIXe siècle pour ses immenses carrières de tuf rose, beige et crème. Cette pierre a marqué de nombreux édifices en Arménie, dont une grande partie d'Erevan, ainsi que le mausolée de Lénine à Moscou. Endommagée par le séisme de 1988, Artik est aujourd'hui un centre de traitement du tuf et du basalte, abritant l'église Saint-Georges et l'église de Lmbatavank du VIIe siècle.",
    },
