      pt: ["Centro da extração de tufo na Arménia.", "A igreja de Lmbatavank data do século VII.", "Localiza-se na província de Shirak.", "Situada a uma altitude de cerca de 1.800 metros.", "A população é de aproximadamente 17.000 pessoas.", "Possui uma importante necrópole da Idade do Bronze."],
