      en: ["Home to the Dilijan National Park, founded in 1958.", "Location of the UWC Dilijan International School.", "Annual rainfall is approximately 640 mm.", "Haghartsin Monastery is located 18 km from the city.", "Located in Tavush Province at up to 1,510 meters.", "Famous for its traditional wooden architecture."],
      es: ["Alberga el Parque Nacional Dilijan, fundado en 1958.", "Sede de la Escuela Internacional UWC Dilijan.", "La precipitación anual es de unos 640 mm.", "El monasterio de Haghartsin se encuentra a 18 km de la ciudad.", "Situada en la provincia de Tavush a 1.510 metros de altitud.", "Conocida por su arquitectura tradicional de madera."],
