    type: "city",
    parent: "AM-SU",
    coords: [46.3314, 39.5256],
    name: { de: "Sisian", hu: "Sziszian", ro: "Sisian", en: "Sisian"},
    image: "/poi-images/armenia-sisian-cities-v2.webp",
    description: {
      de: "Sisian ist eine historische Stadt am Fluss Worotan, umgeben von alten megalithischen Denkmälern und Wasserfällen.",
      hu: "Sziszian történelmi város a Vorotan folyó partján, amelyet ősi megalitikus műemlékek és vízesések vesznek körül.",
      ro: "Sisian este un oraș istoric situat pe râul Vorotan, înconjurat de monumente megalitice antice și cascade.",
      en: "Sisian is a historic city located on the Vorotan River, surrounded by ancient megalithic monuments and waterfalls.",
      es: "Sisian es una ciudad histórica a orillas del río Vorotan, rodeada de antiguos monumentos megalíticos y cascadas.",
      pt: "Sisian é uma cidade histórica nas margens do rio Vorotan, rodeada por antigos monumentos megalíticos e cascatas.",
      fr: "Sisian est une ville historique située sur la rivière Vorotan, entourée d'anciens monuments mégalithiques et de cascades.",
    },
    descriptionAdvanced: {
      de: "Sisian liegt auf rund 1.580 Metern Höhe in der südarmenischen Provinz Sjunik am Fluss Worotan und ist mit etwa 14.000 Einwohnern eine ruhige Hochlandstadt zwischen Eriwan und Goris an der „Nord-Süd-Lebensader“ Armeniens. Die heutige Stadt wurde 1840 vom russischen Zarenreich neu angelegt und hieß bis 1940 Garakilisa; seit 1995 trägt sie den historisch gewachsenen Namen Sisian. Wahrzeichen ist die kreuzkuppelförmige Kirche St. Grigor (auch Sisawan genannt) aus dem 7. Jahrhundert, eine der elegantesten Kirchen Armeniens. Wenige Kilometer nördlich befindet sich der prähistorische Steinkreis Zorats Karer (auch Karahundsch oder „armenisches Stonehenge“), der etwa 7.500 Jahre alt sein und astronomischen Zwecken gedient haben soll. In der Umgebung locken außerdem der Schaki-Wasserfall, das Bergvolksdorf Schinuhajr, mittelalterliche Khatschkare auf den Hochweiden sowie Ferienhütten und Wandertouren in den Bargushat-Bergen.",
      hu: "Sziszian Dél-Örményországban, a Szjunik tartományban, mintegy 1580 méter magasan, a Vorotan folyó partján fekszik, és körülbelül 14 ezer lakosával egy csendes felföldi város a Jereván–Goris észak–déli életvonalán. A mai települést 1840-ben alapították újra orosz cári fennhatóság alatt, és 1940-ig a Garakilisza nevet viselte; 1995 óta hivatalosan a történelmileg kialakult Sziszian nevet használja. Emblematikus épülete a 7. századi Szent Grigor (vagy Sziszavan) kereszt-kupolás temploma, Örményország egyik legelegánsabb temploma. A várostól néhány kilométerre északra található Zorac Karer (más néven Karahundzs vagy „örmény Stonehenge”) kőkör, amely a feltételezések szerint 7500 éves és csillagászati célokat szolgált. A környéken vonzerő még a Saki-vízesés, a hegyvidéki Sinuhajr falu, a felföldi legelőkön található középkori hacskárok, valamint a Barguzsat-hegységben tett túrák és nyaralók.",
      ro: "Sisian este așezat la circa 1.580 m altitudine, în provincia sud-armeană Siunik, pe râul Vorotan, și, cu aproximativ 14.000 de locuitori, este un oraș liniștit de podiș, situat pe axa nord–sud Erevan – Goris, principala arteră a țării. Orașul actual a fost reorganizat în 1840 sub administrația țaristă rusă și s-a numit Garakilisa până în 1940; din 1995 poartă din nou numele istoric Sisian. Reperul său arhitectural este biserica Sf. Grigorie (numită și Sisavan), o biserică cu cupolă pe cruce din secolul al VII-lea, una dintre cele mai elegante din Armenia. La câțiva kilometri nord se află cercul de pietre preistoric Zorats Karer (sau Karahunj, „Stonehenge-ul armean”), considerat a avea aproape 7.500 de ani și funcții astronomice. Atracțiile din jur includ cascada Shaki, satul de munte Shinuhayr, khachkarurile medievale din pășunile alpine, cabanele și traseele de drumeție din munții Bargushat.",
      en: "Sisian sits at around 1,580 metres altitude in the southern Armenian province of Syunik on the Vorotan River, and with about 14,000 inhabitants is a quiet upland town on Armenia's main north–south corridor between Yerevan and Goris. The present town was re-founded in 1840 under Russian imperial rule and was called Garakilisa until 1940; since 1995 it has officially borne its historic name, Sisian. Its architectural emblem is the cross-domed Surb Grigor (Sisavan) church of the 7th century, one of the most elegant churches in Armenia. A few kilometres to the north lies the prehistoric stone circle of Zorats Karer (also Carahunge or 'Armenian Stonehenge'), thought to be some 7,500 years old and to have served astronomical purposes. The area also offers the Shaki waterfall, the mountain village of Shinuhayr, medieval cross-stones in the high pastures and hiking and chalet tourism in the Bargushat range.",
      es: "Sisian se encuentra a 1.580 metros de altitud en la provincia de Syunik, siendo una tranquila ciudad de montaña en la ruta entre Ereván y Goris. Su símbolo es la iglesia de San Grigor (Sisavan) del siglo VII, una de las más elegantes de Armenia. A pocos kilómetros se halla el círculo de piedras prehistórico de Zorats Karer (el 'Stonehenge armenio'), con unos 7.500 años de antigüedad. El entorno natural ofrece atractivos como la cascada de Shaki, khachkars medievales en los pastos de altura y rutas de senderismo por las montañas de Bargushat.",
      pt: "Sisian situa-se a 1.580 metros de altitude na província de Syunik, sendo uma pacata cidade de montanha na rota entre Erevan e Goris. O seu ex-líbris é a igreja de São Grigor (Sisavan) do século VII, uma das mais elegantes da Arménia. A poucos quilómetros encontra-se o círculo de pedras pré-histórico de Zorats Karer (o 'Stonehenge arménio'), com cerca de 7.500 anos. As redondezas oferecem atrações como a cascata de Shaki, khachkars medievais e trilhos para caminhadas nas montanhas Bargushat.",
      fr: "Sisian est perchée à 1 580 mètres d'altitude dans la province de Syunik, sur la rivière Vorotan. C'est une ville de montagne paisible située sur l'axe vital nord-sud de l'Arménie. Son monument emblématique est l'église Saint-Grégoire (Sisavan) du VIIe siècle, l'une des plus élégantes du pays. À quelques kilomètres au nord se trouve le cercle de pierres préhistorique de Zorats Karer (le « Stonehenge arménien »), vieux de 7 500 ans. La région offre également la cascade de Chaki et de superbes sentiers de randonnée dans les montagnes de Bargushat.",
    },
