    description: {
      de: "Stepanawan ist eine nördliche Ferienstadt, geschätzt für ihre Kiefernwälder, ihr kühles Klima und die nahe gelegenen Lori-Berd-Ruinen.",
      hu: "Sztepanavan egy északi üdülőváros, amelyet fenyvesei, hűvös éghajlata és a közeli Lori Berd romjai tesznek népszerűvé.",
      ro: "Stepanavan este un oraș stațiune nordic, prețuit pentru pădurile sale de pin, climatul răcoros și ruinele Lori Berd din apropiere.",
      en: "Stepanavan is a northern resort city, cherished for its pine forests, cool climate, and the nearby Lori Berd ruins.",
      es: "Stepanavan es una ciudad de vacaciones del norte, apreciada por sus bosques de pinos, su clima fresco y las ruinas de Lori Berd.",
      pt: "Stepanavan é uma cidade de férias no norte, apreciada pelos seus pinhais, clima fresco e as ruínas de Lori Berd.",
      fr: "Stepanavan est une ville de villégiature du nord, appréciée pour ses forêts de pins, son climat frais et les ruines de Lori-Berd.",
    },
    descriptionAdvanced: {
      de: "Stepanawan ist eine etwa 13.000 Einwohner zählende Bergstadt im Norden der Provinz Lori, gelegen auf rund 1.400 Metern Höhe am Fluss Dsoraget, in einer von dichten Kiefern- und Fichtenwäldern, Hochweiden und tiefen Schluchten geprägten Landschaft. Bis 1924 hieß die Stadt Dschalaloghli und war eine kleine Karawanenstation; danach wurde sie zu Ehren des bolschewistischen Aktivisten Stepan Schahumjan umbenannt. Bekanntheit weit über die Region hinaus genießt die Stadt durch den 1931 vom polnischen Botanikerpaar Edmund Leonowicz und Sofia Leonowicz angelegten Dendropark Stepanawan – einen 35 Hektar großen Park mit über 500 Baumarten aus aller Welt. In unmittelbarer Nähe liegen die mittelalterliche Festung Lori-Berd auf einem Felsplateau zwischen zwei Schluchten, die romantische Fluss-Schlucht Dsoraget mit ihrem Eco-Resort, sowie zahlreiche Wanderwege; im Winter ist Stepanawan beliebter Ausgangspunkt für Skitouren in den Bazum-Bergen.",
      hu: "Sztepanavan mintegy 13 ezer lakosú hegyi város a Lori tartomány északi részén, körülbelül 1400 méter magasan, a Dzoraget folyó partján, sűrű fenyves- és lucfenyőerdők, hegyi legelők és mély szurdokok övezte tájon. A települést 1924-ig Dzsalaloghli néven ismerték kis karavánállomásként; ezután kapta a bolsevik aktivista, Sztyepan Sahumjan tiszteletére a Sztepanavan nevet. A városon messze túlnyúló hírnevét az 1931-ben Edmund és Sofia Leonowicz lengyel botanikus házaspár által telepített Sztepanavani Dendroparknak köszönheti – ez egy 35 hektáros park, amelyben a világ minden tájáról több mint 500 fafaj található. A közvetlen környéken áll a Lori Berd középkori erőd egy két szurdok közötti sziklaplatón, a romantikus Dzoraget-szurdok ökoüdülővel, és számtalan túraútvonal; télen Sztepanavan kedvelt kiindulópont a Bazum-hegyi sítúrákhoz.",
      ro: "Stepanavan este un oraș de munte cu aproximativ 13.000 de locuitori din nordul provinciei Lori, situat la circa 1.400 m altitudine, pe râul Dzoraget, într-un peisaj de păduri dese de pin și molid, pășuni alpine și defileuri adânci. Până în 1924 localitatea se numea Jalaloghli și era o mică stație de caravane; ulterior a fost rebotezată în onoarea activistului bolșevic Stepan Șahumian. Faima sa, dincolo de granițele regiunii, vine de la Dendroparcul Stepanavan, înființat în 1931 de cuplul de botaniști polonezi Edmund și Sofia Leonowicz – un parc de 35 de hectare cu peste 500 de specii de arbori din întreaga lume. În împrejurimi se află cetatea medievală Lori Berd, ridicată pe un platou stâncos între două defileuri, romanticul defileu Dzoraget cu eco-resortul său și numeroase trasee de drumeție; iarna, Stepanavan este un punct de plecare popular pentru ture de schi în munții Bazum.",
      en: "Stepanavan is a mountain town of about 13,000 people in the northern part of Lori Province, set at roughly 1,400 metres altitude on the Dzoraget River amid a landscape of dense pine and spruce forests, alpine pastures and deep gorges. Until 1924 the town was called Jalaloghli and served as a small caravan stop; it was then renamed in honour of the Bolshevik activist Stepan Shaumyan. Its fame far beyond the region rests on the Stepanavan Dendropark, founded in 1931 by the Polish botanist couple Edmund and Sofia Leonowicz – a 35-hectare arboretum with over 500 tree species from around the world. Just outside the town lie the medieval Lori Berd fortress on a rocky plateau between two gorges, the romantic Dzoraget gorge with its eco-resort, and numerous hiking trails; in winter Stepanavan is a popular base for ski tours in the Bazum range.",
      es: "Situada a 1.400 metros de altitud en la provincia de Lori, Stepanavan es una ciudad de montaña rodeada de densos bosques y profundos desfiladeros. Es famosa por el Dendropark Stepanavan, un jardín botánico de 35 hectáreas con más de 500 especies de árboles, fundado en 1931. En las inmediaciones destaca la fortaleza medieval de Lori Berd, situada en una meseta rocosa entre dos cañones. Su clima alpino y los senderos de las montañas Bazum la convierten en un destino popular tanto para el senderismo estival como para el esquí de travesía en invierno.",
      pt: "Situada a 1.400 metros de altitude na província de Lori, Stepanavan é uma cidade de montanha rodeada por densas florestas e desfiladeiros profundos. É famosa pelo Dendropark Stepanavan, um jardim botânico de 35 hectares com mais de 500 espécies de árvores, fundado em 1931. Nas proximidades destaca-se a fortaleza medieval de Lori Berd, situada num planalto rochoso entre dois desfiladeiros. O seu clima alpino e os trilhos das montanhas Bazum tornam-na um destino popular para caminhadas e esqui de montanha.",
      fr: "Stepanavan est une ville de montagne d'environ 13 000 habitants située dans le nord de la province de Lori, à 1 400 mètres d'altitude. Elle est entourée de forêts de pins, de pâturages et de gorges profondes creusées par la rivière Dsoraget. La ville est célèbre pour son Dendropark, créé en 1931 par un couple de botanistes polonais, qui s'étend sur 35 hectares et abrite plus de 500 espèces d'arbres. À proximité se trouvent la forteresse médiévale de Lori-Berd sur un plateau rocheux et de nombreux sentiers de randonnée à travers les montagnes de Bazum.",
    },
