    coords: [44.2694, 40.8358],
    name: { de: "Spitak", hu: "Szpitak", ro: "Spitak", en: "Spitak"},
    image: "/poi-images/armenia-spitak-cities-v2.webp",
    description: {
      de: "Spitak ist eine wiederaufgebaute Stadt, die durch ein katastrophales Erdbeben im Jahr 1988 fast vollständig zerstört wurde.",
      hu: "Szpitak egy újjáépített város, amelyet az 1988-as katasztrofális földrengés szinte teljesen elpusztított.",
      ro: "Spitak este un oraș reconstruit care a fost aproape complet distrus de un cutremur catastrofal în 1988.",
      en: "Spitak is a rebuilt city that was almost completely destroyed by a catastrophic earthquake in 1988.",
      es: "Spitak es una ciudad reconstruida que fue casi totalmente destruida por un catastrófico terremoto en 1988.",
      pt: "Spitak é uma cidade reconstruída que foi quase totalmente destruída por um terramoto catastrófico em 1988.",
      fr: "Spitak est une ville reconstruite qui fut presque entièrement détruite par un séisme catastrophique en 1988.",
    },
    descriptionAdvanced: {
      de: "Spitak liegt auf rund 1.560 Metern Höhe im Nordwesten Armeniens in der Provinz Lori, etwa 95 Kilometer nördlich von Eriwan, am Fluss Pambak. Der Name bedeutet auf Armenisch „weiß“, in Anspielung auf die schneebedeckten Berghänge der Bazum- und Pambak-Bergketten. Am 7. Dezember 1988 zerstörte das verheerende Spitak-Erdbeben mit einer Stärke von 6,8 die Stadt fast vollständig: Über 25.000 Menschen kamen in der Region ums Leben, etwa 90 Prozent der Gebäude in Spitak stürzten ein. Beim Wiederaufbau halfen rund 110 Länder; ganze Stadtviertel wurden in den 1990er Jahren von ausländischen Bauteams errichtet, unter anderem von Italienern, Schweizern, Norwegern und Estländern, die ihren jeweiligen architektonischen Stil mitbrachten – bis heute heißen Quartiere „italienisches Dorf“ oder „norwegisches Viertel“. Heute hat Spitak rund 12.000 Einwohner, lebt von Lebensmittel- und Holzindustrie, einer modernen Käserei und vom Eisenbahnknoten an der Strecke nach Gjumri.",
      hu: "Szpitak Örményország északnyugati részén, a Lori tartományban fekszik, mintegy 1560 méter magasan, Jerevántól körülbelül 95 kilométerre északra, a Pambak folyó partján. A név örményül „fehéret” jelent, utalva a Bazum- és Pambak-hegyláncok hófedte oldalaira. 1988. december 7-én a 6,8-es erősségű spitaki földrengés a várost gyakorlatilag a földdel tette egyenlővé: a régióban több mint 25 ezer ember halt meg, Szpitakban az épületek mintegy 90 százaléka összeomlott. Az újjáépítésben mintegy 110 ország vett részt; az 1990-es években egész városrészeket építettek külföldi csapatok – olaszok, svájciak, norvégok, észtek –, akik magukkal hozták saját építészeti stílusukat is, és mind a mai napig használatban vannak az „olasz falu” vagy „norvég negyed” elnevezések. Szpitak ma mintegy 12 ezer lakosú város, élelmiszer- és faipari üzemekkel, modern sajtüzemmel és a Gjümri felé vezető vasút csomópontjával.",
      ro: "Spitak se află în nord-vestul Armeniei, în provincia Lori, la circa 1.560 m altitudine, la aproximativ 95 km nord de Erevan, pe râul Pambak. Numele înseamnă „alb” în armeană, o aluzie la versanții acoperiți de zăpadă ai munților Bazum și Pambak. Pe 7 decembrie 1988, devastatorul cutremur de la Spitak, cu magnitudinea 6,8, a distrus aproape complet orașul: peste 25.000 de oameni au murit în regiune, iar circa 90% din clădirile din Spitak s-au prăbușit. La reconstrucție au participat aproximativ 110 țări; în anii 1990, cartiere întregi au fost ridicate de echipe străine – italieni, elvețieni, norvegieni, estonieni – care au adus cu ei și stilul lor arhitectural, motiv pentru care există și astăzi „satul italian” sau „cartierul norvegian”. Astăzi Spitak are aproximativ 12.000 de locuitori, trăiește din industria alimentară și a lemnului, dintr-o brânzărie modernă și din rolul de nod feroviar pe linia spre Gyumri.",
      en: "Spitak lies in north-western Armenia in Lori Province at around 1,560 metres altitude, about 95 km north of Yerevan on the Pambak River. The name means 'white' in Armenian, alluding to the snow-covered slopes of the Bazum and Pambak ranges. On 7 December 1988 the devastating Spitak earthquake of magnitude 6.8 virtually levelled the town: more than 25,000 people died across the region and around 90 percent of buildings in Spitak collapsed. Reconstruction involved some 110 countries; whole districts were built in the 1990s by foreign teams – Italians, Swiss, Norwegians, Estonians – who brought their own architectural styles, leaving names such as the 'Italian village' or 'Norwegian quarter' that survive to this day. Spitak now has around 12,000 inhabitants and lives from food and wood industries, a modern dairy and its role as a railway junction on the line to Gyumri.",
      es: "Spitak se encuentra a 1.560 metros de altitud en la provincia de Lori, junto al río Pambak. Su nombre significa 'blanco', en alusión a las laderas nevadas que la rodean. El 7 de diciembre de 1988, un devastador terremoto de magnitud 6,8 destruyó el 90% de sus edificios. La reconstrucción contó con la ayuda de 110 países; barrios enteros fueron construidos por equipos extranjeros (italianos, suizos, noruegos), lo que dio lugar a distritos con estilos arquitectónicos europeos únicos. Hoy, la ciudad vive de la industria alimentaria y maderera, y es un nudo ferroviario hacia Gyumri.",
      pt: "Spitak situa-se a 1.560 metros de altitude na província de Lori, junto ao rio Pambak. O seu nome significa 'branco', aludindo às encostas nevadas que a rodeiam. A 7 de dezembro de 1988, um terramoto devastador de magnitude 6,8 destruiu 90% dos seus edifícios. A reconstrução contou com a ajuda de 110 países; bairros inteiros foram erguidos por equipas estrangeiras (italianos, suíços, noruegueses), resultando em distritos com estilos arquitetónicos europeus. Hoje, a cidade vive da indústria alimentar e madeireira e é um nó ferroviário para Gyumri.",
      fr: "Spitak se trouve à 1 560 mètres d'altitude dans la province de Lori, au bord de la rivière Pambak. Son nom signifie « blanc » en arménien, en référence aux sommets enneigés des chaînes de Bazum et Pambak. Le 7 décembre 1988, le séisme dévastateur de Spitak, d'une magnitude de 6,8, a presque entièrement rasé la ville. Environ 110 pays ont aidé à sa reconstruction ; des quartiers entiers ont été bâtis par des équipes étrangères (italiennes, norvégiennes, estoniennes), conservant leur style architectural d'origine. La ville compte aujourd'hui 12 000 habitants.",
    },
