    image: "/poi-images/armenia-yeghvard-cities-v2.webp",
    description: {
      de: "Jeghward ist eine kleine historische Stadt in der Region Kotajk, die mittelalterliche Ruinen und alte Kirchen aufweist.",
      hu: "Jehvard egy kis történelmi város a Kotajk régióban, ahol középkori romok és ősi templomok találhatók.",
      ro: "Eghvard este un mic oraș istoric din regiunea Kotaik, cu ruine medievale și biserici vechi.",
      en: "Yeghvard is a small historic city in the Kotayk region, featuring medieval ruins and old churches.",
      es: "Yeghvard es una pequeña ciudad histórica en la región de Kotayk que cuenta con ruinas medievales y antiguas iglesias.",
      pt: "Yeghvard é uma pequena cidade histórica na região de Kotayk, que possui ruínas medievais e igrejas antigas.",
      fr: "Yeghvard est une petite ville historique de la région de Kotayk, présentant des ruines médiévales et des églises anciennes.",
    },
    descriptionAdvanced: {
      de: "Jeghward liegt auf einer Hochebene auf rund 1.300 Metern Höhe in der Provinz Kotajk, nur etwa 18 Kilometer nördlich von Eriwan, und ist eine kleine Stadt mit etwa 11.000 Einwohnern. Trotz ihrer geringen Größe blickt sie auf eine sehr lange Geschichte zurück: Die Gegend war bereits im 3. Jahrtausend v. Chr. besiedelt, was eine bronzezeitliche Festung und mehrere Felsgräber dokumentieren. Im Mittelalter gehörte Jeghward der Familie Proschjan, die hier 1301 eine ungewöhnliche zweistöckige Kirche der Heiligen Mutter Gottes (Sourb Astwazazin) errichtete – das Erdgeschoss diente als Mausoleum, das Obergeschoss als Kirche; die Ruinen sind bis heute erhalten und ein wertvolles Denkmal armenischer Architektur. Die heutige Stadt entstand 1996 durch Eingemeindung mehrerer Dörfer und entwickelt sich als Vorort Eriwans rasch: Wohnungsbau, Gartenbau, Gewächshäuser für Tomaten, Gurken und Erdbeeren sowie kleine IT-Dienstleister machen Jeghward zu einem dynamischen Pendlerstandort.",
      hu: "Jehvard egy fennsíkon, mintegy 1300 méter magasan fekszik a Kotajk tartományban, Jerevántól csupán 18 kilométerre északra, és kicsi, mintegy 11 ezer lakosú város. Méreteihez képest azonban igen hosszú történelmet tudhat magáénak: a környéket már Krisztus előtt 3000 körül lakták, amit egy bronzkori erőd és számos sziklasír is bizonyít. A középkorban a Prosjan család birtoka volt, akik 1301-ben szokatlan kétszintes Istenanya-templomot (Szurb Asztvacacin) emeltek itt – a földszint mauzóleumként, az emelet templomként szolgált; romjai máig állnak és az örmény építészet értékes emlékei. A jelenlegi várost 1996-ban hozták létre több falu egyesítésével, és Jereván külvárosaként rohamosan fejlődik: lakóparkok, kertgazdálkodás, paradicsom-, uborka- és epertermelő üvegházak, valamint kis informatikai szolgáltatók teszik dinamikus ingázási céllá.",
      ro: "Eghvard este așezat pe un platou la circa 1.300 m altitudine, în provincia Kotaik, la doar 18 km nord de Erevan, fiind un orășel cu aproximativ 11.000 de locuitori. În ciuda dimensiunilor sale modeste, are o istorie foarte îndelungată: zona a fost locuită încă din mileniul al III-lea î.Hr., după cum atestă o cetate din epoca bronzului și mai multe morminte rupestre. În Evul Mediu Eghvard aparținea familiei Proșian, care a ridicat aici, în 1301, o biserică neobișnuită cu două nivele dedicată Maicii Domnului (Surp Astvațațin) – parterul folosit ca mausoleu, iar etajul ca biserică; ruinele sale se păstrează până azi și constituie un monument prețios al arhitecturii armene. Orașul actual a fost format în 1996 prin unirea mai multor sate și se dezvoltă rapid ca suburbie a Erevanului: ansambluri rezidențiale, grădinărit, sere de roșii, castraveți și căpșuni, precum și mici firme IT îl transformă într-un punct dinamic de navetism.",
      en: "Yeghvard sits on an upland plateau at around 1,300 metres altitude in Kotayk Province, only about 18 km north of Yerevan, and is a small town of around 11,000 inhabitants. Despite its modest size it can boast a very long history: the area was inhabited as early as the 3rd millennium BC, as attested by a Bronze Age fortress and a number of rock-cut tombs. In the Middle Ages Yeghvard belonged to the Proshyan family, who in 1301 built an unusual two-storey church of the Holy Mother of God (Surb Astvatsatsin) here – the ground floor used as a mausoleum and the upper floor as a church; its ruins still survive as a precious monument of Armenian architecture. The present town was created in 1996 by merging several villages and is developing fast as a Yerevan suburb: housing estates, market gardens, greenhouses for tomatoes, cucumbers and strawberries, and small IT firms turn Yeghvard into a dynamic commuter base.",
      es: "Yeghvard se encuentra en una meseta a unos 1.300 metros de altitud en la provincia de Kotayk, a solo 18 kilómetros al norte de Ereván, y es una pequeña ciudad de unos 11.000 habitantes. A pesar de su reducido tamaño, posee una historia muy larga: la zona ya estaba habitada en el tercer milenio a. C., como documentan una fortaleza de la Edad del Bronce y varias tumbas rupestres. En la Edad Media, Yeghvard perteneció a la familia Proshyan, que construyó allí en 1301 una inusual iglesia de dos plantas dedicada a la Santa Madre de Dios (Sourb Astvatsatsin); la planta baja servía de mausoleo y la superior de iglesia, cuyas ruinas se conservan como un valioso monumento de la arquitectura armenia. La ciudad actual surgió en 1996 por la unión de varios pueblos y se desarrolla rápidamente como suburbio de Ereván: la construcción de viviendas, la horticultura, los invernaderos de tomates y fresas, así como pequeños proveedores de servicios informáticos, hacen de Yeghvard un dinámico lugar de residencia para trabajadores pendulares.",
      pt: "Yeghvard situa-se num planalto a cerca de 1.300 metros de altitude na província de Kotayk, apenas a 18 quilômetros a norte de Erevan, sendo uma pequena cidade com cerca de 11.000 habitantes. Apesar do tamanho, tem uma história muito longa: a área já era habitada no terceiro milênio a.C., como documentado por uma fortaleza da Idade do Bronze. Na Idade Média, Yeghvard pertenceu à família Proshyan, que em 1301 construiu uma invulgar igreja de dois andares da Santa Mãe de Deus (Sourb Astvatsatsin) – o rés-do-chão servia de mausoléu e o andar superior de igreja; as ruínas são hoje um monumento valioso. A cidade atual surgiu em 1996 e desenvolve-se rapidamente como subúrbio de Erevan, com horticultura e serviços de TI.",
      fr: "Yeghvard est située sur un plateau à environ 1 300 mètres d'altitude dans la province de Kotayk, à seulement 18 kilomètres au nord d'Erevan, et compte environ 11 000 habitants. Malgré sa petite taille, elle possède une très longue histoire : la région était déjà habitée au IIIe millénaire av. J.-C., comme en témoignent une forteresse de l'âge du bronze et plusieurs tombes rupestres. Au Moyen Âge, Yeghvard appartenait à la famille Proshyan, qui y fit construire en 1301 une église inhabituelle à deux étages dédiée à la Sainte Mère de Dieu (Sourb Astvatsatsin) — le rez-de-chaussée servait de mausolée et l'étage supérieur d'église ; les ruinas sont encore visibles aujourd'hui. La ville actuelle s'est développée depuis 1996 comme banlieue d'Erevan, avec une agriculture dynamique (serres de tomates et fraises) et de petits services informatiques.",
    },
