      ro: ["Biserica Surb Astvatsatsin a fost finalizată în 1321.", "Una dintre cele mai vechi localități locuite continuu din Armenia.", "Situat la aproximativ 18 km nord de Erevan.", "Populația este de circa 12.000 de locuitori.", "Sediul unor mari crame și fabrici.", "Aflat la o altitudine de 1.330 de metri."],
      en: ["Surb Astvatsatsin Church was completed in 1321.", "One of the oldest continuously inhabited places in Armenia.", "Located about 18 km north of Yerevan.", "Population is approximately 12,000 people.", "Home to major wineries and factories.", "Situated at an altitude of 1,330 meters."],
      es: ["La iglesia de Surb Astvatsatsin se terminó en 1321.", "Uno de los lugares habitados continuamente más antiguos de Armenia.", "Situada a unos 18 km al norte de Ereván.", "La población es de unos 12.000 habitantes.", "Sede de grandes bodegas y fábricas.", "Se encuentra a una altitud de 1.330 metros."],
      pt: ["A igreja de Surb-Astvatsatsin foi concluída em 1321.", "Um dos locais continuamente habitados mais antigos da Armênia.", "Situa-se a cerca de 18 km a norte de Erevan.", "A população é de cerca de 12.000 habitantes.", "Sede de grandes vinícolas e fábricas.", "Localiza-se a uma altitude de 1.330 metros."],
