      pt: ["Nomeada em homenagem a Alexander Myasnikyan.", "Situada na margem sul do lago Sevan.", "Localiza-se na província de Gegharkunik.", "A população é de cerca de 11.000 habitantes.", "Situa-se a uma altitude de 1.930 metros.", "Antigamente chamava-se Mets Kznut."],
      fr: ["Nommée d'après Alexander Myasnikyan.", "Située sur la rive sud du lac Sevan.", "Se trouve dans la province de Gegharkunik.", "La population est d'environ 11 000 habitants.", "Située à une altitude de 1 930 mètres.", "S'appelait autrefois Mets Kznut."],
