    type: "city",
    parent: "AM-AR",
    coords: [44.2869, 40.1436],
    name: { de: "Mezamor", hu: "Mecamor", ro: "Mețamor", en: "Metsamor"},
    image: "/poi-images/armenia-metsamor-cities-v2.webp",
    description: {
      de: "Mezamor ist eine moderne Stadt, die gebaut wurde, um die Arbeiter des einzigen armenischen Kernkraftwerks zu beherbergen.",
      hu: "Mecamor egy modern város, amelyet Örményország egyetlen atomerőművének dolgozói számára építettek.",
      ro: "Mețamor este un oraș modern construit pentru a găzdui muncitorii singurei centrale nucleare din Armenia.",
      en: "Metsamor is a modern city built to house the workers of Armenia's only nuclear power plant.",
      es: "Metsamor es una ciudad moderna construida para albergar a los trabajadores de la única central nuclear de Armenia.",
      pt: "Metsamor é uma cidade moderna construída para alojar os trabalhadores da única central nuclear da Arménia.",
      fr: "Mezamor est une ville moderne construite pour loger les ouvriers de la seule centrale nucléaire arménienne.",
    },
    descriptionAdvanced: {
      de: "Mezamor liegt rund 35 Kilometer westlich von Eriwan in der Ararat-Ebene auf etwa 850 Metern Höhe und ist eine kleine, kompakt geplante Stadt mit etwa 9.500 Einwohnern, die in den 1960er und 1970er Jahren als Wohnort für die Beschäftigten des einzigen armenischen Kernkraftwerks errichtet wurde. Das Atomkraftwerk Mezamor (auch Armenisches Kernkraftwerk genannt) ging 1976 mit zwei sowjetischen WWER-440-Reaktoren in Betrieb; nach dem Erdbeben von 1988 vorübergehend stillgelegt, wurde Block 2 1995 wieder hochgefahren und liefert seither bis zu 40 Prozent des Stroms in Armenien, ein wichtiger Faktor während der Energieblockade der 1990er Jahre. Wenige Kilometer von der Stadt entfernt liegt die archäologische Stätte Mezamor, eine der bedeutendsten Bronze- und Eisenzeit-Siedlungen der Region: hier wurden Keramik, Schmiedereste, Metallurgieöfen und sogar mögliche frühe astronomische Beobachtungspunkte gefunden. Der Ort ist somit ein eigenartiges Zusammentreffen von 5.000 Jahre alter Metallurgie und moderner Kerntechnik.",
      hu: "Mecamor Jerevántól mintegy 35 kilométerre nyugatra, az Ararát-síkságon, körülbelül 850 méter magasan fekszik, és egy kompakt, tervezetten épített kisváros mintegy 9500 lakossal, amelyet az 1960–70-es években emeltek Örményország egyetlen atomerőművének dolgozói számára. A mecamori (Örmény) Atomerőmű 1976-ban indult be két szovjet VVER-440 reaktorral; az 1988-as földrengés után átmenetileg leállították, majd 1995-ben a 2-es blokkot újraindították, és azóta Örményország áramellátásának akár 40 százalékát is biztosítja – kulcsszerepet játszott az 1990-es évek energiablokádja idején. A várostól néhány kilométerre található Mecamor régészeti lelőhelye, a régió egyik legjelentősebb bronz- és vaskori települése, ahol kerámiamaradványokat, kohászati maradványokat, fémolvasztó kemencéket és vélhetően korai csillagászati megfigyelőhelyeket is feltártak. Mecamor így a 5000 éves kohászat és a modern atomtechnika sajátos találkozási pontja.",
      ro: "Mețamor se află la circa 35 km vest de Erevan, în câmpia Ararat, la aproximativ 850 m altitudine, și este un oraș mic și planificat compact, cu aproximativ 9.500 de locuitori, construit în anii 1960–70 pentru a găzdui personalul singurei centrale nucleare din Armenia. Centrala nucleară de la Mețamor (numită și Centrala Nucleară Armeană) a fost pusă în funcțiune în 1976 cu două reactoare sovietice WWER-440; oprită temporar după cutremurul din 1988, unitatea 2 a fost repornită în 1995 și asigură de atunci până la 40% din electricitatea Armeniei, jucând un rol esențial în timpul blocadei energetice din anii 1990. La câțiva kilometri de oraș se află situl arheologic Mețamor, una dintre cele mai importante așezări din epoca bronzului și a fierului din regiune, unde au fost descoperite ceramică, urme de metalurgie, cuptoare de topit metale și posibile puncte timpurii de observație astronomică. Mețamor este astfel o întâlnire neobișnuită între metalurgia veche de 5.000 de ani și tehnologia nucleară modernă.",
      en: "Metsamor lies about 35 km west of Yerevan on the Ararat plain at roughly 850 metres altitude and is a small, compactly planned town of around 9,500 inhabitants, built in the 1960s and 1970s to house the workforce of Armenia's only nuclear power plant. The Metsamor (Armenian) Nuclear Power Plant came on line in 1976 with two Soviet VVER-440 reactors; temporarily shut down after the 1988 earthquake, Unit 2 was restarted in 1995 and has since supplied up to 40 percent of Armenia's electricity, a vital lifeline during the energy blockade of the 1990s. A few kilometres from the town lies the archaeological site of Metsamor, one of the most important Bronze and Iron Age settlements in the region, where pottery, metallurgical remains, smelting furnaces and possible early astronomical observation points have been uncovered. Metsamor thus represents a remarkable encounter between 5,000-year-old metallurgy and modern nuclear technology.",
      es: "Situada a 35 kilómetros al oeste de Ereván, Metsamor es una ciudad planificada en los años 60 y 70 para los empleados de la central nuclear homónima. La planta entró en funcionamiento en 1976 y hoy suministra hasta el 40% de la electricidad de Armenia. A pocos kilómetros se encuentra el yacimiento arqueológico de Metsamor, uno de los asentamientos más importantes de la Edad del Bronce y del Hierro en la región, donde se han hallado hornos metalúrgicos y posibles observatorios astronómicos tempranos. El lugar representa una curiosa coexistencia entre metalurgia de 5.000 años de antigüedad y tecnología nuclear moderna.",
      pt: "Localizada a 35 quilómetros a oeste de Erevan, Metsamor é uma cidade planeada nas décadas de 60 e 70 para os funcionários da central nuclear homónima. A central entrou em funcionamento em 1976 e fornece hoje até 40% da eletricidade da Arménia. A poucos quilómetros encontra-se o sítio arqueológico de Metsamor, um dos povoados mais importantes da Idade do Bronze e do Ferro na região, onde foram encontrados fornos metalúrgicos e possíveis observatórios astronómicos precoces. O local representa uma curiosa coexistência entre metalurgia com 5.000 anos e tecnologia nuclear moderna.",
      fr: "Mezamor, située à environ 35 kilomètres à l'ouest d'Erevan, est une petite ville planifiée dans les années 1960 et 1970 pour les employés de l'unique centrale nucléaire du pays. La centrale est entrée en service en 1976 ; après un arrêt temporaire suite au séisme de 1988, elle fournit aujourd'hui jusqu'à 40 % de l'électricité de l'Arménie. À quelques kilomètres se trouve le site archéologique de Mezamor, l'un des plus importants de l'âge du bronze et du fer dans la région, où ont été découverts des vestiges de métallurgie et d'anciens points d'observation astronomique. Le lieu offre ainsi un contraste saisissant entre 5 000 ans d'histoire métallurgique et le génie nucléaire moderne.",
    },
