      pt: ["Sede da única central nuclear do Cáucaso.", "A central entrou em funcionamento em 1976.", "O sítio arqueológico data do IV milénio a.C.", "A população é de cerca de 9.500 habitantes.", "Localiza-se na província de Armavir.", "Foi planeada como um povoado soviético modelo."],
      fr: ["Siège de l'unique centrale nucléaire du Caucase.", "La centrale a été mise en service en 1976.", "Le site archéologique remonte au IVe millénaire av. J.-C.", "La population est d'environ 9 500 habitants.", "Se situe dans la province d'Armavir.", "Conçue comme une cité modèle soviétique."],
