      en: "Vayk is a small town in southern Armenia, nestled in a valley and surrounded by rugged mountain terrain.",
      es: "Vayk es una pequeña ciudad en el sur de Armenia, enclavada en un valle y rodeada de un accidentado terreno montañoso.",
